(window.ST=window.ST||{}).stories=[{"id":"atlab_aang","name":"Aang","chapters":[{"id":"atlab_aang_farewell","i":0,"title":null,"req":null,"reward":null,"side":false,"lines":[{"a":"atlab_aang","t":"Comerciante! O Appa acordou!"},{"a":"atlab_aang","t":"Então... Acho que está na hora nos despedirmos..."},{"a":"atlab_sokka","t":"Ah, não fica assim! Podemos voltar a qualquer hora!"},{"a":"atlab_aang","t":"Isso mesmo! Você lembra o caminho, Sokka?"},{"a":"atlab_sokka","t":"Ah... Eu não estava prestando atenção..."},{"a":"atlab_sokka","t":"Mas enfim! Temos uma coisa superimportante de Avatar para resolver!"},{"a":"atlab_sokka","t":"Vamos, Momo! Estamos indo embora!"},{"a":"atlab_aang","t":"Momo! ...Momo?"},{"a":"atlab_aang","t":"Você gostou daqui, não foi? Tá bom, tudo bem."},{"a":"atlab_aang","t":"Comerciante, se importa de cuidar do Momo por um tempinho?"},{"a":"atlab_aang","t":"Eu volto para te buscar depois, Momo. Prometo!"},{"a":"atlab_aang","t":"Vamos, Sokka. Obrigado por tudo, Comerciante!"},{"a":"atlab_sokka","t":"Tchau!"},{"a":"atlab_aang","t":"Vamos, Appa! Yip yip!"}]},{"id":"atlab_aang_01","i":1,"title":"Caminho Errado","req":"atlab_aang:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fichas da fortuna"},"side":false,"lines":[{"a":"inn","t":"Foi mal, garoto, não entendi. Pode repetir tudo do começo?"},{"a":"atlab_aang","t":"Foi mal! Deixa eu começar de novo!"},{"a":"atlab_aang","t":"Eu sou Aang, o Avatar."},{"a":"atlab_aang","t":"Meus amigos e eu estávamos viajando no meu bisão voador..."},{"a":"atlab_aang","t":"Acho que pegamos o caminho errado enquanto voávamos e acabamos aqui!"},{"a":"inn","t":"Aquele boi grandão lá fora? Aquilo voa?"},{"a":"atlab_aang","t":"Sim! O nome dele é Appa. Ele é muito simpático!"},{"a":"inn","t":"Ele parece estar muito cansado. Tem alguém atrás de vocês, né?"},{"a":"atlab_aang","t":"Ah, é..."},{"a":"inn","t":"Ah, não se preocupe com isso. Não vou deixar ninguém se machucar debaixo do meu teto. Promessa do Oscar."},{"a":"inn","t":"Olha só, o que vocês acham de ficar aqui de graça?"},{"a":"atlab_aang","t":"De graça? Jura!?"},{"a":"inn","t":"É, para começo de conversa, acho que esse dinheiro estranho de vocês nem vale por aqui."},{"a":"inn","t":"E eu não posso deixar um bando de crianças dormindo na rua, não é?"},{"a":"atlab_aang","t":"Valeu mesmo, Sr. Oscar!"},{"a":"inn","t":"Vocês parecem muito talentosos, que tal retribuir o favor ajudando uma pessoa na loja dela?"},{"a":"atlab_aang","t":"Claro! Agradecemos demais!"}]},{"id":"atlab_aang_02","i":2,"title":"Dobra de fogo?","req":"atlab_aang:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fichas da fortuna"},"side":false,"lines":[{"a":"inn","t":"Ei, Lilu! Vem conhecer meu novo amigo aqui!"},{"a":"lilu","t":"Olá! Eu nunca vi tatuagens assim antes..."},{"a":"atlab_aang","t":"Eu sou Aang! E eu nunca vi um chapéu assim também!"},{"a":"inn","t":"Vai lá, Aang, mostra para ela o seu truque!"},{"a":"atlab_aang","t":"Você quer dizer... isso?"},{"a":"lilu","t":"Como você faz isso? Eu não senti nenhuma magia!"},{"a":"atlab_aang","t":"É dobra de ar! Eu também posso dobrar a terra e a água!"},{"a":"lilu","t":"Que incrível! Espera aí, deixa eu anotar..."},{"a":"lilu","t":"Pode ser Chi? Eu nunca vi alguém fazer isso antes..."},{"a":"atlab_aang","t":"Isso mesmo! Mas nem todo mundo consegue, só as pessoas que nascem com essa habilidade podem aprender e dominar!"},{"a":"lilu","t":"Você disse que pode dobrar o ar, a terra e a água... mas e o fogo?"},{"a":"atlab_aang","t":"Ah... é que... Eu ainda não dominei a dobra do fogo..."},{"a":"atlab_aang","t":"...Eu ainda não encontrei um mestre de dobra de fogo para me ensinar."},{"a":"lilu","t":"É mesmo? Eu sei conheço algumas magias de fogo!"},{"a":"lilu","t":"Não é exatamente a mesma coisa, mas talvez você queira ver como funciona!"},{"a":"atlab_aang","t":"Ah... claro. Valeu, Lilu."}]},{"id":"atlab_aang_03","i":3,"title":"O último mestre do ar","req":"atlab_aang:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fichas da fortuna"},"side":false,"lines":[{"a":"elderowen","t":"Aang, meu rapaz. Você está gostando da vida na cidade?"},{"a":"atlab_aang","t":"Ancião Owen! Ela é ótima! Obrigado a hospitalidade."},{"a":"elderowen","t":"Não é nada. Mas diga-me, meu jovem, onde estão seus pais?"},{"a":"atlab_aang","t":"Ah... Eu não... tenho mais pais."},{"a":"atlab_aang","t":"Minha família... todos os Nômades do Ar foram assassinados pela Nação do Fogo."},{"a":"atlab_aang","t":"...Eu sou o último."},{"a":"elderowen","t":"Minha nossa! Meus pêsames, pobre garoto..."},{"a":"elderowen","t":"... Se você não tem para onde voltar, que tal ficar aqui com seus amigos?"},{"a":"elderowen","t":"Tenho certeza de que a cidade adoraria que você ficasse aqui. Você já é bem popular!"},{"a":"atlab_aang","t":"Obrigado pela oferta, Ancião... mas não posso aceitar."},{"a":"atlab_aang","t":"Neste exato momento, o Senhor do Fogo Ozai está tramando sua próxima ação."},{"a":"atlab_aang","t":"Quando o Cometa de Sozin iluminar o céu outra vez, a Nação do Fogo vai conquistar meu mundo..."},{"a":"atlab_aang","t":"... O Reino da Terra... as Tribos da Água... todos vão sofrer o mesmo destino que os Nômades do Ar."},{"a":"atlab_aang","t":"Como o Avatar, eu sou o único que pode detê-lo! ...mas ainda não estou pronto."},{"a":"elderowen","t":"Que fardo terrível para uma criança carregar..."},{"a":"elderowen","t":"Mas saiba que você todo o apoio da nossa cidade."},{"a":"atlab_aang","t":"Obrigado, Ancião. Você já fez muito por nós!"},{"a":"atlab_aang","t":"Vamos lembrar de fazer uma visita quando tudo isso acabar!"}]},{"id":"atlab_aang_04","i":4,"title":"Presságio de Sozin","req":"atlab_aang:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fichas da fortuna"},"side":false,"lines":[{"a":"mana","t":"Avatar. Nossos caminhos finalmente se encontraram."},{"a":"atlab_aang","t":"Quem é você? Como me conhece?"},{"a":"mana","t":"A presença do Avatar brilha como um farol para o Terceiro Olho."},{"a":"atlab_aang","t":"Ah, eu não gosto de leitura de cartas... Passo!"},{"a":"mana","t":"Você, que é muitos, mas ainda não está completo..."},{"a":"mana","t":"Uma terrível batalha contra o Senhor do Fogo o aguarda."},{"a":"atlab_aang","t":"O Senhor do Fogo Ozai... Você conhece ele?"},{"a":"mana","t":"Sob o olhar do Cometa, a terra será destroçada e os campos se tornarão cinzas!"},{"a":"atlab_aang","t":"Eu sei! Mas o que eu devo fazer?"},{"a":"mana","t":"O fluxo do destino não pode ser quebrado."},{"a":"atlab_aang","t":"..."},{"a":"mana","t":"... mas os corajosos podem manipulá-lo para guiar o caminho."},{"a":"mana","t":"Um aliado improvável e uma aliança frágil podem ser a chave."},{"a":"atlab_aang","t":"Obrigado, cartomante... Vou pensar nisso."},{"a":"mana","t":"..."},{"a":"mana","t":"Seja corajoso, Avatar. Confie em si mesmo e você triunfará."}]}]},{"id":"argon","name":"Argon","chapters":[{"id":"argon_01","i":1,"title":"A sombra do rei","req":"argon:1","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"argon","t":"...E foi quando eu finquei minha espada no troubelin! Zás!"},{"a":"elderowen","t":"Haha! Que bela história, Argon!"},{"a":"elderowen","t":"Ah, o ardor da juventude..."},{"a":"elderowen","t":"É muito gentil da sua parte acompanhar esse velhote em sua caminhada matinal."},{"a":"argon","t":"O prazer é meu! Se eu for me tornar um cavaleiro algum dia, devo ajudar as pessoas!"},{"a":"elderowen","t":"Assim como seu pai, né? Tenho certeza de que você será um bom cavaleiro, garoto."},{"a":"elderowen","t":"Talvez você possa até trabalhar como guarda real do rei!"},{"a":"elderowen","t":"Falando nele, olha lá ele no mercado! Por que você não pergunta a ele?"},{"a":"argon","t":"VOSSA MAJESTADE! Eu vim lhe oferecer meus serviços como cavaleiro!"},{"a":"king","t":"O que significa disso? Sia, por favor, cuide deste plebeu!"},{"a":"sia","t":"Claro, meu rei."},{"a":"sia","t":"E então, meu jovem? O que foi?"},{"a":"argon","t":"Uau! Eu, hum..."},{"a":"argon","t":"Meu nome é cavaleiro! Eu quero me tornar um Argon!"},{"a":"argon","t":"Não, espere um segundo..."},{"a":"sia","t":"Você certamente tem coragem!"},{"a":"sia","t":"Se você está tão determinado assim, venha me ver no pátio do castelo na próxima semana."},{"a":"sia","t":"Treine bastante até lá! Eu não aceitaria um folgado entre os cavaleiros do rei..."}]},{"id":"argon_02","i":2,"title":"Treinamento variado","req":"argon:2","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"lilu","t":"Argon, o que você está fazendo aqui?"},{"a":"argon","t":"Treinando bastante! Eu finalmente terei a chance de me tornar um cavaleiro para o rei!"},{"a":"lilu","t":"O rei?... Ou sua misteriosa conselheira, Sia?"},{"a":"argon","t":"Esse é o nome dela? É lindo também!"},{"a":"lilu","t":"..."},{"a":"argon","t":"Aff! Não! Apenas o rei importa!"},{"a":"argon","t":"Eu preciso me tornar um cavaleiro! Nada mais importa!"},{"a":"lilu","t":"Certo... Deixe-me ajudar com seus ferimentos."},{"a":"argon","t":"Obrigado! Ai! Este feitiço dói!"}]},{"id":"argon_03","i":3,"title":"Dois lados de uma moeda","req":"argon:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"argon","t":"Beleza! Sia vai aparecer a qualquer momento agora!"},{"a":"argon","t":"Meu treinamento valeu a pena, estou pronto!"},{"a":"argon","t":"...Mas ainda estou nervoso demais..."},{"a":"argon","t":"Ah! Olá! Você aí, nos arbustos!"},{"a":"yami","t":"...!"},{"a":"argon","t":"Você está aqui para se tornar uma cavaleira também?"},{"a":"argon","t":"Sia estará aqui em breve! Não precisa se esconder, ela é bem legal!"},{"a":"yami","t":"Sia...!"},{"a":"yami","t":"Eu preciso ir. Adeus."},{"a":"argon","t":"E-espere!"},{"a":"argon","t":"Uau! Bomba de fumaça!?"},{"a":"argon","t":"Que garota estranha..."},{"a":"sia","t":"Com quem você está falando?"},{"a":"argon","t":"Ah, Sia! Apenas uma viajante tímida! Nada importante!"},{"a":"sia","t":"...Ok. Bem, parece que sua determinação continua firme e forte."},{"a":"sia","t":"Está pronto para arriscar sua vida como um dos cavaleiros do Rei?"},{"a":"argon","t":"Pode apostar! Di-digo, claro! Vou deixar meu pai orgulhoso!"},{"a":"sia","t":"Ótimo. Para sua primeira missão, tenho um importante evento chegando..."}]},{"id":"argon_04","i":4,"title":"De mãos vazias","req":"yami:4","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"argon","t":"..."},{"a":"sia","t":"Você só pode estar brincando!"},{"a":"sia","t":"Você encurralou a assassina... e não conseguiu detê-la."},{"a":"sia","t":"E está me dizendo que DEIXOU ELA IR porque acha que ela é uma boa pessoa?"},{"a":"argon","t":"..."},{"a":"sia","t":"Que absurdo é esse?"},{"a":"sia","t":"Você percebeu que esta assassina tentou matar nosso Rei - o mesmo homem que você jurou proteger, não?"},{"a":"sia","t":"Um incidente como esse coloca em perigo muito mais do que sua mente fraca consegue entender."},{"a":"sia","t":"Ugh... suponho que seja o Rei quem decide sobre a demissão de um cavaleiro..."},{"a":"sia","t":"...Mas nem pense que falarei bem de você. Dispensado."},{"a":"argon","t":"..."},{"a":"argon","t":"Caramba..."},{"a":"argon","t":"Sinto muito, pai."}]},{"id":"argon_a","i":4,"title":"A Torre dos Titãs","req":"argon:4","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fichas da fortuna"},"side":true,"lines":[{"a":"elderowen","t":"A Torre dos Titãs, é?"},{"a":"lilu","t":"Fale mais sobre ela!"},{"a":"argon","t":"Eu já ouvi alguns heróis sussurrando sobre ela, mas nunca vi..."},{"a":"elderowen","t":"De fato, a Torre dos Titãs é um lugar mítico. Ninguém sabe se ela existe mesmo."},{"a":"elderowen","t":"De acordo com as histórias, ela aparece do nada, desafiando os mais poderosos Heróis a subirem seus vários níveis..."},{"a":"elderowen","t":"...até desaparecer subitamente, apagando as memórias de quem a viu."},{"a":"argon","t":"A-apagando as memórias!?"},{"a":"lilu","t":"Que estranho... então, de onde vem a lenda?"},{"a":"argon","t":"Pois é! Algumas pessoas precisariam lembrar!"},{"a":"elderowen","t":"Dizem que as pessoas que superam o desafio dos Titãs são consideradas dignas pela Torre."},{"a":"elderowen","t":"Esses heróis voltam... mudados pela experiência e com as memórias intactas."},{"a":"elderowen","t":"De forma mais clara, parte deles fica na Torre e parte da Torre fica com eles."},{"a":"elderowen","t":"... Essa é a história de hoje. Obrigado por ouvir as lendas desse velho aqui."},{"a":"lilu","t":"Uau! Será que ela existe mesmo?"},{"a":"argon","t":"É! Eu adoraria explorar uma masmorra assim!"},{"a":"lilu","t":"Mas tem algo de estranho nisso... Como o Owen sabia disso tudo?"},{"a":"argon","t":"...!"}]},{"id":"argon_05","i":5,"title":"Cavaleiro errante","req":"argon:5","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"argon","t":"Suspiro..."},{"a":"steel","t":"Se não é Argon! Como vai você?"},{"a":"argon","t":"Ah, oi, Brohm... Tem algum serviço pra mim?"},{"a":"steel","t":"Hoje não, senhor cavaleiro! Por que essa cara?"},{"a":"argon","t":"Pode me chamar só de Argon. Eu... perdi o meu título."},{"a":"steel","t":"Ui, isso deve doer..."},{"a":"steel","t":"Não importa o que aconteça, fique de cabeça erguida! Você vai superar!"},{"a":"steel","t":"Aposto que a sua sorte logo vai virar!"},{"a":"argon","t":"Certo... Valeu, Brohm."},{"a":"argon","t":"Eu vou... ficar pela praça enquanto isso."},{"a":"argon","t":"Suspiro..."}]},{"id":"argon_b","i":5,"title":"Nós somos os Titãs?","req":"argon:5","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fichas da fortuna"},"side":true,"lines":[{"a":"lilu","t":"Bom dia... Argon."},{"a":"argon","t":"Aaahh.... Dia."},{"a":"lilu","t":"... Você também está sentindo, não está?"},{"a":"argon","t":"Sim, estou acabado! Sinto que lutei a noite toda!"},{"a":"lilu","t":"Olha, seu escudo está todo acabado também!"},{"a":"argon","t":"Quê? É verdade! Eu jurava que ele estava brilhando ontem..."},{"a":"lilu","t":"Argon... Será que...?"},{"a":"polonia","t":"Ahoy! Algum de vocês andadores da terra veio ao mercado em busca de <c1>Grevas do Juggernaut</c1>?"},{"a":"lilu","t":"Não... especialmente não 20 delas! Onde arrumou tudo isso!?"},{"a":"polonia","t":"Ah! Boa pergunta. Não faço ideia."},{"a":"polonia","t":"Acho que estou saqueando enquanto durmo. Deve ser meu espírito pirata, arrg!"},{"a":"lilu","t":"E aquela pirata também..."},{"a":"lilu","t":"... Será que todos nós desafiamos a Torre e perdemos nossas memórias...?"},{"a":"argon","t":"Quer dizer que não fomos fortes o suficiente..."},{"a":"argon","t":"Vou treinar bastante para a próxima vez! Você vai ver!"}]},{"id":"argon_06","i":6,"title":"Segunda luz","req":"argon:6","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"sia","t":"E então, esse... \"Cavaleiro\" estava com a sua assassina à mercê..."},{"a":"sia","t":"...Mas decidiu deixá-la ir, pois acreditava que ela era uma boa pessoa!"},{"a":"king","t":"Fascinante! Esse novo cavaleiro parece muito promissor!"},{"a":"sia","t":"Com todo o respeito, meu rei..."},{"a":"sia","t":"Esse homem não deu um fim à sua assassina por causa uma mera intuição."},{"a":"king","t":"A marca de um <c1>paladino</c1>, não acha?"},{"a":"sia","t":"Como é?"},{"a":"king","t":"Ter um inimigo à sua mercê, mas ver além da crueza da guerra e do conflito..."},{"a":"king","t":"...E deixá-lo ir, com tanta certeza das possibilidades de redenção que está disposto a arriscar seu título."},{"a":"king","t":"Um ato de tremenda bravura e benevolência!"},{"a":"sia","t":"Eu... admito que não considerei essa perspectiva, meu rei."},{"a":"sia","t":"Mas o reino não vê um aspirante a paladino há décadas..."},{"a":"sia","t":"Devo convocar o conselho de cavaleiros pra debater a questão?"},{"a":"king","t":"Bobagem! Eu mesmo cuido das formalidades."},{"a":"sia","t":"Como quiser, meu rei. Vou preparar uma escolta agora mesmo."},{"a":"king","t":"Não tem por quê. Serei bem discreto!"}]},{"id":"argon_07","i":7,"title":"O rei discreto","req":"argon:7","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"king","t":"Afastem-se, plebeus! Um trabalhador comum caminha entre vocês!"},{"a":"tavern","t":"Ah, Rei Reinhold! Já faz um tempo. Quer que abra um barril de ambrosia?"},{"a":"king","t":"Shhh! Estou à paisana hoje! Não me dê atenção!"},{"a":"tavern","t":"Ah, é claro! Que bobagem, a minha!"},{"a":"king","t":"Você aí que se esconde atrás do balcão!"},{"a":"argon","t":"Ah! Hã, desculpe, Vossa Majestade. Eu vou sair do caminho..."},{"a":"king","t":"Bobagem! Um aprendiz de paladino é mais que digno de sentar-se em meu radiante entorno!"},{"a":"argon","t":"Sentar ao lado do... paladino!?"},{"a":"king","t":"Correto! Em minha infinita sabedoria, senti enorme potencial dentro de você!"},{"a":"king","t":"Apesar de seus... métodos incomuns, seu coração é puro e seu senso de justiça é... admirável!"},{"a":"king","t":"Doravante, o reino o considera digno de assumir o Teste do Paladino!"},{"a":"argon","t":"Um Teste de Paladino... uau!"},{"a":"argon","t":"Eu sei tudo a respeito! Cada um é único e decidido pelo próprio paladino..."},{"a":"argon","t":"Precisa ser uma tarefa perigosa, tipo matar um dragão... ou destruir um artefato antigo..."},{"a":"king","t":"Deveras! Qualquer ato suficientemente bravo e altruísta em nome do reino serve!"},{"a":"argon","t":"Entendi! Obrigado, Vossa Majestade! Não vai se arrepender!"},{"a":"king","t":"É claro que não, eu estou sempre certo!"},{"a":"king","t":"...Agora, já que estou à paisana..."},{"a":"king","t":"Você aí! Velho! Me ensine a jogar carteado!"},{"a":"master","t":"Carteado, é? O velho Theodore só joga a dinheiro..."}]},{"id":"argon_08","i":8,"title":"Renascido","req":"argon:8","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"lilu","t":"Argon! Por que a pressa?"},{"a":"argon","t":"Eu vou ser um Paladino, Lilu!"},{"a":"lilu","t":"Um Paladino! Isso é incrível, Argon! Como...?"},{"a":"argon","t":"O Rei disse que eu deveria enfrentar uma provação! Essa é a única forma de ser digno do título de Paladino."},{"a":"lilu","t":"Uma provação... Você sabe o que vai fazer?"},{"a":"argon","t":"..."},{"a":"argon","t":"Ah, não! Não faço ideia!"},{"a":"argon","t":"Precisa ser algo de proporções épicas e gloriosas..."},{"a":"lilu","t":"Mas, Argon, você é glorioso! Você derrotou monstros em todo lugar..."},{"a":"argon","t":"Sim, mas preciso fazer mais alguma coisa..."},{"a":"argon","t":"Ouvi dizer que existem demônios emplumados no Pico da Desolação, talvez isso seja suficiente..."},{"a":"lilu","t":"Bom, seja lá o que for, você vai dar conta!"},{"a":"argon","t":"Obrigado, Lilu... Mesmo quando eu não era mais Cavaleiro, você continuou acreditando em mim..."},{"a":"lilu","t":"Ah! I-Isso não foi nada!"},{"a":"lilu","t":"Enfim! Você vai precisar de ajuda nessa missão! Vou preparar alguns pergaminhos de cura para você!"},{"a":"argon","t":"Incrível! Avante!"}]},{"id":"argon_09","i":9,"title":"Confronto da Desolação (Argon)","req":"argon:9","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"argon","t":"Argh... que lugar chato!"},{"a":"argon","t":"Toda essa subida e nenhum sinal de Harpias... Eu fui até atacado por assassinos!"},{"a":"argon","t":"... Eles pareciam com aquela menina ninja, não é?"},{"a":"argon","t":"Que bom que a Lilu me deu esses pergaminhos de cura, ufa!"},{"a":"argon","t":"Acho que vou descansar um pouco aqui."},{"a":"argon","t":"...Hã?"},{"a":"yami","t":"Você de novo."},{"a":"argon","t":"A... A assassina do Rei!"},{"a":"argon","t":"Deve ser o destino. Uma recompensa ainda maior que a Harpia!"},{"a":"yami","t":"... Pode vir. Eu vou matar você aí mesmo."}]},{"id":"argon_10a","i":10,"title":"Retorno triunfal","req":"yami:9","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"argon","t":"Rei Reinhold! Missão cumprida!"},{"a":"king","t":"Que maravilha! Que tipo de criatura tenebrosa você abateu?"},{"a":"argon","t":"É... falando nisso."},{"a":"yami","t":"...Oi."},{"a":"king","t":"O... o que significa isso!?"},{"a":"sia","t":"Guardas! Prendam os dois!"},{"a":"argon","t":"Opa! Espera! Ela está diferente!"},{"a":"king","t":"É mesmo?"},{"a":"yami","t":"Eu vim... pedir desculpas."},{"a":"sia","t":"Meu Rei, tenho certeza de que você não acreditaria..."},{"a":"argon","t":"Eu posso testemunhar por ela! Por minha honra de cavaleiro!"},{"a":"king","t":"Muito bem! Então ouvirei as desculpas!"},{"a":"sia","t":"Ahh... Eu temia que isso fosse acontecer."},{"a":"sia","t":"Guardas! Tragam reforços e observem todos os passos dela!"},{"a":"sia","t":"Argon, espere lá fora enquanto conversamos com esta... intrusa."},{"a":"argon","t":"Já!"},{"a":"argon","t":"(... Será que cometi um grande erro?)"}]},{"id":"argon_10b","i":11,"title":"Redentor","req":"yami:10","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"sia","t":"Argh... Essa dor de cabeça era a última coisa de que eu precisava."},{"a":"argon","t":"Lady Sia! O que aconteceu?"},{"a":"sia","t":"... Por incrível que pareça, o Rei Reinhold está disposto a perdoar aquela que o mataria."},{"a":"sia","t":"Embora eu tenha as minhas dúvidas, ela nos deu informações valiosas sobre a Ordem de Azuman."},{"a":"argon","t":"Então... isso significa que..."},{"a":"sia","t":"Sim, vamos aceitar a rendição dela como pedido de desculpas."},{"a":"sia","t":"Ela está sob cuidados médicos pois estava faminta, mas vai se recuperar."},{"a":"sia","t":"E você, Paladino Argon..."},{"a":"argon","t":"Pa... Paladino!"},{"a":"sia","t":"Sim, uma coisa é aniquilar uma ameaça, já redimir um inimigo jurado do reino..."},{"a":"sia","t":"Parece que o Rei Reinhold estava certo sobre você, afinal."},{"a":"sia","t":"Agora vá comemorar, Paladino. Tenho certeza de que você ficará muito ocupado muito em breve!"},{"a":"argon","t":"Eu vou! Obrigado!"},{"a":"argon","t":"Pai... espero que você esteja orgulhoso."}]},{"id":"argon_epilogue","i":12,"title":"Epílogo","req":"argon:10","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"lilu","t":"Pa... Paladino!? Você conseguiu, Argon!"},{"a":"argon","t":"Por um momento achei que eu havia estragado tudo..."},{"a":"argon","t":"Mas meu pai estava certo. Eu só precisava seguir o meu coração!"},{"a":"lilu","t":"Ah... Isso quer dizer que vão te mandar em missões em outros continentes?"},{"a":"argon","t":"Ainda não. Lady Sia quer que eu ensine os Heróis a se tornarem Paladinos."},{"a":"lilu","t":"Ah! Que alívio!... Mas é difícil imaginar você como professor."},{"a":"lilu","t":"Você não vai ficar ocupado com as missões superimportantes de Paladino?"},{"a":"argon","t":"Eu vou dar o meu melhor! O reino está contando comigo!"},{"a":"tavern","t":"Olá, nobre Paladino!"},{"a":"tavern","t":"O Brohm me disse que estava procurando mais luvas de fundição!"},{"a":"argon","t":"Claro! É para já!"},{"a":"lilu","t":"... Algumas coisas nunca mudam, né?"},{"a":"tavern","t":"Não o nosso Argon, não mesmo."}]},{"id":"argon_c","i":13,"title":"Escrito na Pedra","req":"malady:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fichas da fortuna"},"side":true,"lines":[{"a":"argon_stone","t":"..."},{"a":"lilu","t":"A poção... não funcionou, né?"},{"a":"lilu","t":"Ai, ai... E a gente se esforçou tanto..."},{"a":"lilu","t":"Foi mal, Argon. Não fui boa o suficiente... Espero que não esteja tão desconfortável aí."},{"a":"elderowen","t":"Hmm... realmente, péssimas notícias."},{"a":"lilu","t":"Ainda não estamos sem poções, mas..."},{"a":"lilu","t":"...É muito difícil quando ele não está conosco."},{"a":"elderowen","t":"A cidade parece bem vazia sem ele, não é?"},{"a":"lilu","t":"...Como uma festa de aniversário sem os amigos."},{"a":"lilu","t":"...Ficar resmungando não vai trazer ele de volta. Vou continuar tentando."},{"a":"lilu","t":"Podemos pedir ajuda ao Donovan."},{"a":"lilu","t":"Vai custar caro, mas podemos fazer uma vaquinha!"},{"a":"lilu","t":"Sei que você não vai sair daí, mas... aguenta firme! A gente vai te salvar!"},{"a":"argon_stone","t":"..."}]}]},{"id":"ashley","name":"Ashley","chapters":[{"id":"ashley_01","i":1,"title":"A samurai incomum","req":"ashley:1","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"argon","t":"Uma samurai de verdade... Mal posso esperar!"},{"a":"argon","t":"Senhora samurai! Eu sou Argon! Cavaleiro em treinamento."},{"a":"ashley","t":"Opa. Eu sou a Ashley. Como vai?"},{"a":"argon","t":"O...opa?"},{"a":"tavern","t":"Tire os pés da mesa, por favor!"},{"a":"ashley","t":"Pff. Tudo bem."},{"a":"ashley","t":"E aí? Do que você precisa?"},{"a":"argon","t":"Ah... samurais não costumam ter muita disciplina e tudo mais?"},{"a":"ashley","t":"Quê? É, o pessoal de onde eu venho é bem cri-cri com isso."},{"a":"ashley","t":"Agora eu tô livre. Só uma ronin. Uma samurai sem mestre."},{"a":"argon","t":"Ah, entendi... Tudo bem!"},{"a":"argon","t":"Eu planejava fazer uma missão com a Lilu no Castelo Assombrado, mas..."},{"a":"argon","t":"Vou precisar ir para a Sala de Treinamento! Pode ir no meu lugar?"},{"a":"ashley","t":"Claro. Mas você vai ficar me devendo essa, cavaleiro."}]},{"id":"ashley_02","i":2,"title":"Armada e preparada","req":"ashley:2","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"ashley","t":"Você é a Lilu, né?"},{"a":"lilu","t":"Isso mesmo! É um prazer conhecer você!"},{"a":"ashley","t":"Muito bem, então, vamos lá."},{"a":"lilu","t":"Espera! Calma aí!"},{"a":"lilu","t":"Ainda não nos preparamos! Precisamos de poções, comidas e..."},{"a":"ashley","t":"Tanto faz, não precisamos de nada disso."},{"a":"ashley","t":"Vivemos ou morremos. Não tem meio-termo."},{"a":"lilu","t":"Isso é... Não! Isso é imprudente!"},{"a":"ashley","t":"Eu tô indo. É por aqui, né?"},{"a":"lilu","t":"Não! Por aí é a Floresta Uivante..."},{"a":"argon","t":"Hm... Boa sorte?"}]},{"id":"ashley_03","i":3,"title":"Limite da vida","req":"ashley:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"ashley","t":"Vocês só tem isso, monstros? PODEM VIR!"},{"a":"lilu","t":"Ashley! Vai com calma! A minha cura não consegue acompanhar!"},{"a":"ashley","t":"Isso... não é... NADA!!!"},{"a":"ashley","t":"Ufa... foi um bom aquecimento, né?"},{"a":"lilu","t":"Tá brincando?! Você quase morreu!"},{"a":"lilu","t":"Agindo assim, não me surpreende que você tenha perdido um braço!"},{"a":"ashley","t":"Opa. Aquilo foi diferente."},{"a":"ashley","t":"Aquele erro... não vai se repetir."},{"a":"lilu","t":"Hunf. Eu não vou usar anestesia para essa cura."},{"a":"lilu","t":"Isso é culpa sua. Pode se preparar."},{"a":"ashley","t":"Haha... ha... Eu aguento..."},{"a":"ashley","t":"Ai! Ai, ai, ai..."}]},{"id":"ashley_a","i":4,"title":"Sensação familiar","req":"ashley:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fichas da fortuna"},"side":true,"lines":[{"a":"ashley","t":"Opa. Qual é a desses monstrinhos por aqui?"},{"a":"elven","t":"Estes são os meus caros familiares. Saudações."},{"a":"elven","t":"Campeões Dignos podem vir aqui adotar um deles como fiel companheiro."},{"a":"ashley","t":"Ah. Mascotes, né? Saquei."},{"a":"ashley","t":"Beleza. Você, verdinho. Vou chamar você de <c1>Encrenqueiro</c1>. Vem comigo."},{"a":"ashley","t":"Você é uma fofura, <c1>Bola de Neve</c1>. Vou levar você."},{"a":"elven","t":"Ah... eu temo que..."},{"a":"ashley","t":"Argh, que pássaro feio!"},{"a":"ashley","t":"Vou chamar você de <c1>Pardal</c1>. Pode vir também."},{"a":"elven","t":"... Muito bem. Divirtam-se."}]},{"id":"ashley_04","i":5,"title":"Missão Falhou com Sucesso","req":"ashley:4","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"argon","t":"Como foi sua missão ontem? A Lilu parecia bem chateada..."},{"a":"ashley","t":"Eu voltei com vida. Infelizmente."},{"a":"argon","t":"Hã?! Isso não é bom?"},{"a":"king","t":"Saudações, plebeus! Sintam-se livres para contemplar meu esplendor!"},{"a":"ashley","t":"Ah, senhor Rei, senhor! Ashley apresentando-se para o serviço!"},{"a":"king","t":"Eu gosto de soldados assim! Continue o bom trabalho!"},{"a":"ashley","t":"Sim, senhor! Obrigada, senhor!"},{"a":"tavern","t":"Desculpe, Reinhold, a colheita ainda não chegou."},{"a":"king","t":"Muito bem! Eu voltarei pela manhã!"},{"a":"argon","t":"O que foi isso?"},{"a":"ashley","t":"Ah, hm. Eu costumava servir a um senhor. É o costume."},{"a":"argon","t":"Legal! Me conta mais!"},{"a":"ashley","t":"Não."}]},{"id":"ashley_05","i":6,"title":"A Virada do Conto","req":"ashley:5","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"ashley","t":"... E aí eu disse para ele..."},{"a":"ashley","t":"\"Armada e preparada? Pode dizer que eu estou preparada!\""},{"a":"argon","t":"Hahaha!"},{"a":"argon","t":"Mas... Ashley, e aquela história do senhor de antes..."},{"a":"ashley","t":"Ah, cara... você nunca vai esquecer disso? Tá."},{"a":"ashley","t":"Samurais têm um senhor, um daimiô. Servimos e protegemos eles com nossas vidas."},{"a":"argon","t":"Quanta honra!"},{"a":"ashley","t":"Em um dia como qualquer outro, ele estava comendo..."},{"a":"ashley","t":"E aí, bum. Ninjas. Por toda parte. E todos... todos queriam a cabeça do meu senhor."},{"a":"ashley","t":"Lutamos bastante. Não foi a primeira vez, mas..."},{"a":"ashley","t":"Me acertaram em cheio. Perdi meu braço."},{"a":"ashley","t":"Então... eu fugi. Deixei ele para morrer."},{"a":"argon","t":"Ashley..."},{"a":"ashley","t":"AAAAAAAAH!!! Eu devia ter morrido ali mesmo!"},{"a":"ashley","t":"Naya, me traz mais uma."},{"a":"tavern","t":"Você já bebeu demais hoje, Ashley."},{"a":"ashley","t":"Tá. Tá bom. Eu já passei da conta."},{"a":"ashley","t":"Certo. Argon, diga à Lilu que a Ashley vai partir em uma missão perigosíssima."},{"a":"argon","t":"Hã? Agora?!"},{"a":"ashley","t":"Isso mesmo. Eu vou... acho que para as Cavernas da Aurora. Melhor se apressar!"}]},{"id":"ashley_06","i":7,"title":"Um Olho por um Eu","req":"ashley:6","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"ashley","t":"Menina ninja... Você estava escutando?"},{"a":"yami","t":"Um pouco... Vamos conversar lá fora?"},{"a":"ashley","t":"Ha! Eu não estou a fim de lutar."},{"a":"yami","t":"Meu clã fez aquilo com o Senhor Kusunoki. Eu sou uma pária, mas talvez minhas desculpas..."},{"a":"ashley","t":"Obrigada, mas não precisa. Eu não odeio vocês. Eu me odeio."},{"a":"yami","t":"Eu entendo... Talvez mais do que você possa imaginar."},{"a":"yami","t":"Mas mesmo com a sua honra em frangalhos, você ainda tem muito pelo que viver."},{"a":"yami","t":"Você tem amigos aqui. Uma cidade, uma família. Mascotes que ama."},{"a":"yami","t":"Mas... se nada disso for o bastante, posso oferecer um duelo honrável até a morte."},{"a":"ashley","t":"Um assassinato grátis de uma ninja? Você me mima demais."},{"a":"ashley","t":"Vou passar. Mas obrigada, vou lembrar disso."},{"a":"yami","t":"Como quiser."}]},{"id":"ashley_07","i":8,"title":"Uma Última Luta","req":"ashley:7","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"lilu","t":"Huff... Huff... A Ashley não está aqui..."},{"a":"lilu","t":"Ela se perdeu de novo...?"},{"a":"lilu","t":"Não... espera. Ela me enganou?"},{"a":"ashley","t":"Eu achei que estava indo para o Vulcão do Lago Cinzento..."},{"a":"ashley","t":"Tanto faz, já basta."},{"a":"ashley","t":"Eeeei! Acordem, seus idiotas! A Ashley tá aqui!"},{"a":"monster_Grotto_Mob","t":"A humana está... bêbada?"},{"a":"ashley","t":"Sem curandeiro chato dessa vez, só eu e a vontade de morrer! Só vou parar quando cair morta!"},{"a":"ashley","t":"Eu vou vencer, não importa o que aconteça! Então, quem vem primeiro?"},{"a":"monster_Ruins_Mob","t":"Argh! Cai dentro!"},{"a":"ashley","t":"É assim que se fala!"}]},{"id":"ashley_08","i":9,"title":"Deus Ex Asthea","req":"ashley:8","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"priest","t":"Pela Deusa... esse lugar...?"},{"a":"priest","t":"Nossa, que carnificina."},{"a":"monster_Grotto_Mob","t":"Hehehe."},{"a":"priest","t":"Desculpem, monstros. Permitam-me recuperar minha companhia."},{"a":"monster_Grotto_Mob","t":"Não! NÃO! Ela nos enganou! Aquela samurai já era, ela vai morrer!"},{"a":"priest","t":"Ela ainda está viva. Nossa Ashley é mais forte que isso."},{"a":"monster_Ruins_Mob","t":"É? Então é melhor terminar o serviço!"},{"a":"priest","t":"Você não vai fazer isso."},{"a":"monster_Grotto_Mob","t":"Hahaha! E o que VOCÊ vai fazer? Nos curar?"},{"a":"priest","t":"Vocês não me dão escolha. Que a Deusa Asthea os perdoe..."},{"a":"priest","t":"Porque eu não vou."}]},{"id":"ashley_09","i":10,"title":"Pressão de Repouso","req":"ashley:9","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"ashley","t":"...Ugh..."},{"a":"priest","t":"Finalmente, você acordou."},{"a":"ashley","t":"Hã? Droga... não, você também. Como... Como me encontrou?"},{"a":"priest","t":"Parece que a Deusa se importa com você. Ela me enviou."},{"a":"ashley","t":"Droga... Ah, me deixa logo morrer."},{"a":"priest","t":"Se é o que você quer mesmo."},{"a":"ashley","t":"Aaahhh... finalmente..."},{"a":"ashley","t":"..."},{"a":"ashley","t":"Então... por que ainda está me CURANDO?"},{"a":"priest","t":"Apesar das suas palavras, você parece querer viver."},{"a":"priest","t":"A magia de cura apenas acelera a sua força vital. Se quisesse mesmo morrer, eu não poderia fazer nada para salvá-la."},{"a":"ashley","t":"É mesmo...?"},{"a":"priest","t":"Agora descanse. Você tem muito sobre o que refletir."}]},{"id":"ashley_10","i":11,"title":"Um Tempo para Pensar","req":"ashley:10","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"argon","t":"Você voltou! A Lilu estava te procurando por toda parte!"},{"a":"argon","t":"...Você está com uma cara meio detonada, também."},{"a":"ashley","t":"Não ligues a isso, fui remendado. Levei um sermão também."},{"a":"argon","t":"Da Freyja? Isso é difícil de imaginar."},{"a":"ashley","t":"É. Ela me disse pra começar a pensar. Então eu tô pensando."},{"a":"tavern","t":"Pensando? Que novidade!"},{"a":"ashley","t":"Pare com isso."},{"a":"ashley","t":"...é o que eu gostaria de dizer, mas você tem razão."},{"a":"ashley","t":"Tanto tempo preso ao passado, esqueci até de pensar."},{"a":"argon","t":"Pensar no quê?"},{"a":"ashley","t":"Hmm. Muitas coisas."},{"a":"ashley","t":"Sem que eu percebesse, parece que juntei muitas coisas que me eram queridas."},{"a":"ashley","t":"A cidade. O povo. O lojista. Você também, jovem cavaleiro."},{"a":"ashley","t":"Só precisei de alguns encontros com a morte para perceber. Acho que sou meio lerdo, heh."},{"a":"argon","t":"Sinto-me honrado, senhorita Samurai!"},{"a":"ashley","t":"Ainda um Ronin aqui. Não espere que isso mude tão cedo."},{"a":"yami","t":"..."},{"a":"yami","t":"..."}]},{"id":"ashley_epilogue","i":12,"title":"Epílogo","req":"ashley:11","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"ashley","t":"Ei, Lilu. Estou indo para outra missão. Quer vir comigo?"},{"a":"lilu","t":"Hunf! Para você me mandar para o lugar errado de novo?"},{"a":"lilu","t":"Ou se jogar contra monstros sem pensar direito para eu precisar te costurar de novo?"},{"a":"ashley","t":"Não, eu sou uma nova mulher agora. Vou pegar leve, com uma mão nas costas."},{"a":"lilu","t":"Hm... se está dizendo."},{"a":"lilu","t":"Espera aí..."},{"a":"ashley","t":"Haha! É brincadeira."},{"a":"ashley","t":"Se você cuidar de mim, eu cuido de você."},{"a":"lilu","t":"Ótimo! Mas dessa vez, me promete."},{"a":"lilu","t":"Se as coisas ficarem muito feias... vamos recuar. VOCÊ vai recuar."},{"a":"ashley","t":"Eu prometo. Pela honra de ronin."},{"a":"ashley","t":"Afinal de contas, precisamos voltar para quem amamos."}]}]},{"id":"bjorn","name":"Bjorn","chapters":[{"id":"bjorn_01","i":1,"title":"O Papai Chegou","req":"bjorn:1","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"bjorn","t":"Oi, crianças! O papai chegou!"},{"a":"steel","t":"Pai!"},{"a":"wood","t":"... pai."},{"a":"bjorn","t":"Que cara é essa, Gorza?"},{"a":"wood","t":"Você passou meses fora!"},{"a":"bjorn","t":"A vida de Guarda Florestal é assim! Nas matas, bem longe de casa."},{"a":"wood","t":"Pff. Não custava nada passar aqui mais vezes."},{"a":"bjorn","t":"Quem me dera, mas o Vulcão do Lago Cinzento deixa a gente ocupado!"},{"a":"wood","t":"O Vulcão? Achei que você tivesse saído pra investigar o Pico da Desolação..."},{"a":"bjorn","t":"Foi?"},{"a":"bjorn","t":"Então confundi tudo! Haha!"},{"a":"bjorn","t":"Enfim, eu trouxe lembrancinhas pra vocês! Olhem só!"},{"a":"steel","t":"Ah! Tomara que seja uma Pelúcia de Crocante!"}]},{"id":"bjorn_a","i":1,"title":"Bamham Amigão","req":"bjorn:1","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fichas da fortuna"},"side":true,"lines":[{"a":"bjorn","t":"Ei, crianças, podem cuidar do Bamham um instante?"},{"a":"wood","t":"Esse javali sujo? Sem chance. Você cuida dele."},{"a":"steel","t":"Sem querer ofender, pai, mas ele é meio... maluco."},{"a":"bjorn","t":"Ah, não diga isso! Ele é a coisa mais fofa do mundo!"},{"a":"wood","t":"Pai, sempre que você deixa ele de lado, ele sai quebrando tudo."},{"a":"bjorn","t":"Aquela vez foi só um acidente. Ele ficou empolgado demais."},{"a":"wood","t":"Mas e todas as outras vezes?"},{"a":"bjorn","t":"Também foram... acidentes. O Bamhamzinho não machucaria uma mosca!"},{"a":"wood","t":"Ah, machucaria sim, e ia gostar."},{"a":"wood","t":"Olha, pai, é melhor você carregar essa coisa com você enquanto está na cidade."},{"a":"steel","t":"Pra segurança de todo mundo."},{"a":"bjorn","t":"Tudo bem, tudo bem. Eu entendi. Tudo bem, Bamham, eu te amo."},{"a":"bjorn","t":"Opa, opa, opa! Calma, Bamham!"}]},{"id":"bjorn_02","i":2,"title":"Lista de Afazeres de Bjorn","req":"bjorn:2","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"bjorn","t":"Valeu pela recepção calorosa, pessoal! É bom estar de volta!"},{"a":"elderowen","t":"Que bom que você voltou bem. Você sumiu por meses, já estávamos começando a pensar no pior..."},{"a":"bjorn","t":"Foi mal, foi mal! Vocês sabem como a vida de Guarda Florestal é! Haha!"},{"a":"oils","t":"Se eu te conheço bem, já deve estar pensando na próxima expedição!"},{"a":"bjorn","t":"Haha! E se conhece! Saímos amanhã de manhã cedinho!"},{"a":"oils","t":"Nunca mude, Bjorn. Eu vou ficar de olho no Brohm e na Gorza enquanto você está fora."},{"a":"oils","t":"E, se puder, será que você pode pegar alguns Luzgumelos pra mim?"},{"a":"bjorn","t":"Mas pode deixar! Não é nada!"},{"a":"elderowen","t":"Ah... e as minhas costas estão reclamando esses dias. Será que pode procurar Pérolas Gélidas?"},{"a":"bjorn","t":"Não precisava nem pedir. Vou ficar de olho, Ancião."},{"a":"engineer","t":"Ah! Bjorn! Eu preciso de algumas Escamas de Wyrms da Ferrugem para um experimento, é pedir muito?"},{"a":"bjorn","t":"Claro que não. Anotado!"},{"a":"bjorn","t":"É...! Acho melhor pegarmos mais bolsas, Bamham!"}]},{"id":"bjorn_03","i":3,"title":"Tudo O Que Reluz é Ouro","req":"bjorn:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"bjorn","t":"Hm... Também tá sentindo esse cheiro, Bamham?"},{"a":"bjorn","t":"É isso aí, metal. Devem ser detritos. Vai lá, Bam, procura e pega!"},{"a":"bjorn","t":"Bom garoto, deixa eu ver..."},{"a":"bjorn","t":"Ha. Que dispositivo estranho. Não devem ter deixado pra trás por acidente..."},{"a":"bjorn","t":"E se eu puxar essa alavanca aqui..."},{"a":"bjorn","t":"Hm... é, bem como eu suspeitei."},{"a":"bjorn","t":"Quebrou. Parece que não aprendemos muito, né? Haha!"},{"a":"bjorn","t":"Mas acho que temos uma pista. Passamos meses procurando, e isso não tava aqui da última vez."},{"a":"bjorn","t":"É melhor voltar e perguntar pra quem entende disso. Não sou bom com tecnologia!"}]},{"id":"bjorn_04","i":4,"title":"Emissor Desconhecido","req":"bjorn:4","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"engineer","t":"Que coisa mais estranha! Nunca vi nada parecido."},{"a":"engineer","t":"Parece combinar magia e ciência para funcionar como um tipo de... emissor? Radar?"},{"a":"engineer","t":"Você disse que estava quebrado quando você encontrou, não foi?"},{"a":"bjorn","t":"É. Mas que azar, né? Haha!"},{"a":"engineer","t":"Que pena. Posso dizer uma coisa: isso aqui envia algum tipo de informação. Mas não consigo descobrir mais nada."},{"a":"engineer","t":"Mas olha só, se esperar um instante, posso construir um dispositivo que pode ajudar você a encontrar mais desses... \"Emissores de Magia\"."},{"a":"bjorn","t":"Ótimo! O que acha de voltarmos lá, Bamham?"},{"a":"bjorn","t":"Não sabemos o que essas coisas são... mas não podem ser boas."},{"a":"bjorn","t":"Precisamos descobrir quem está por trás disso!"},{"a":"engineer","t":"Boa sorte! E... tomem cuidado com tecnologias misteriosas!"}]}]},{"id":"donovan","name":"Donovan","chapters":[{"id":"donovan_01","i":1,"title":"Receita original","req":"donovan:1","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"herbalist","t":"Boas-vindas ao Empório de remédios da Maribel! Como posso ajudar?"},{"a":"donovan","t":"Lady Maribel, sim? Gostaria de elogiá-la pessoalmente por sua última criação."},{"a":"donovan","t":"Como inventor da poção de renovação, seu projeto modificado é absolutamente genial!"},{"a":"donovan","t":"A simples adição de uma pitada de flor do pico da névoa é uma melhoria avassaladora!"},{"a":"herbalist","t":"Espere aí... Quer dizer que você é O Donovan? Não pode ser!"},{"a":"herbalist","t":"O projeto da poção de renovação foi inventado há uns 700 anos..."},{"a":"herbalist","t":"Mesmo sendo um elfo, você não parece ter mais de 150!"},{"a":"donovan","t":"É muito gentil, Lady Maribel."},{"a":"donovan","t":"Digamos que nem todos os meus projetos estão disponíveis para as lojas..."},{"a":"donovan","t":"Mas aposto que uma alquimista genial como você não teria problemas em aprendê-los."},{"a":"donovan","t":"Agora, posso dar uma olhada na flor do pico da névoa?"}]},{"id":"donovan_02","i":2,"title":"Terra da fartura","req":"donovan:2","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"donovan","t":"Fascinante... Até as maçãs comuns da região são de excelente qualidade."},{"a":"donovan","t":"Mas como pode ser?"},{"a":"lilu","t":"Se tem alguém que pode explicar, é a Juniper!"},{"a":"lilu","t":"Ah, desculpe! Não queria me meter na sua conversa com aquela... árvore."},{"a":"donovan","t":"Oh, uma donzela com chapéu de aba larga e sua leal coruja..."},{"a":"donovan","t":"Sem dúvida, você deve ser a srta. Lilu."},{"a":"lilu","t":"Isso mesmo! E você, sr. Donovan, obviamente não precisa de apresentações!"},{"a":"donovan","t":"Ouvi muitas coisas sobre a estimada pupila desta cidade. O prazer é todo meu."},{"a":"donovan","t":"Agora, srta. Lilu. Você dizia..."},{"a":"lilu","t":"Ah, sim! Juniper vive falando de como a terra ao redor da cidade transborda de vida..."},{"a":"lilu","t":"É um dos motivos por que ela gosta tanto de cuidar das plantas por aqui."},{"a":"lilu","t":"De todo modo, eu estava indo para as Cavernas da Aurora. Foi um prazer, sr. Donovan!"},{"a":"donovan","t":"Espero revê-la em breve."},{"a":"donovan","t":"Hmm... Talvez essa donzela saiba de alguma coisa..."},{"a":"donovan","t":"Kern... esgotado? Tudo parece muito mais vibrante neste reino."},{"a":"donovan","t":"Vou fazer uma visita à jardineira. Se os ingredientes são mais potentes por aqui..."},{"a":"donovan","t":"... Então eu preciso tirar proveito disso."}]},{"id":"donovan_03","i":3,"title":"Por trás da máscara","req":"donovan:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"lilu","t":"Me chamou, Senhorita Sia?"},{"a":"sia","t":"Ah, Lilu. Obrigada por ter vindo tão rápido."},{"a":"sia","t":"... Acredito que você já conheça o Donovan, não é?"},{"a":"lilu","t":"Ah, sim! Ele é uma lenda entre os alquimistas! Fiquei muito feliz por conhecê-lo!"},{"a":"sia","t":"Aproxime-se desse homem com muito cuidado."},{"a":"lilu","t":"O quê? Mas ele é tão educado! E muito inteligente também..."},{"a":"sia","t":"As aparências podem enganar. Por trás daquela máscara jovem existe um velho milenar, astuto e ardiloso."},{"a":"lilu","t":"Milenar? Mas isso é raro até para elfos! Você acha que..."},{"a":"sia","t":"Sim. Algumas pessoas acreditam que ele descobriu algum tipo de elixir da imortalidade."},{"a":"lilu","t":"Nossa! Eu não me incomodaria com essa receita no meu grimório!"},{"a":"sia","t":"Muitos reis também não. Suspeito que ele esteja controlando o Imperador Kern."},{"a":"lilu","t":"...A política é mesmo complexa."},{"a":"lilu","t":"Mas obrigada! Eu vou tomar cuidado perto dele!"},{"a":"sia","t":"Eu sabia que você entenderia."},{"a":"sia","t":"E eu vou garantir que ele fique longe do nosso... reizinho sugestionável."},{"a":"lilu","t":"É... talvez seja melhor assim."}]},{"id":"donovan_a","i":3,"title":"Isso é um roubo","req":"donovan:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fichas da fortuna"},"side":true,"lines":[{"a":"leather","t":"Ei, ô da poção, tem um segundinho?"},{"a":"donovan","t":"Droga... vagabundos."},{"a":"donovan","t":"A quem devo esse... prazer?"},{"a":"leather","t":"Sou o Tamas. Cuido do couro."},{"a":"leather","t":"Ouvi por aí que você desenrola um elixir da imortalidade. Pode liberar um pra mim?"},{"a":"donovan","t":"...Não faço a menor ideia de como essa história surgiu."},{"a":"donovan","t":"E, mesmo que isso fosse verdade, com certeza eu não sairia dando algo tão valioso."},{"a":"leather","t":"Eu te dou dez moedas de ouro."},{"a":"donovan","t":"Definitivamente NÃO. Guerras foram travadas por essa receita! Imperadores do mundo todo já imploraram só para provar!"},{"a":"leather","t":"Você é difícil de convencer, cara. Quinze moedas, é minha última oferta."},{"a":"donovan","t":"Por acaso o cheiro do couro apodreceu o seu cérebro? Eu não dividiria essa receita nem por todo o ouro do mundo!"},{"a":"donovan","t":"Eu vou embora. Nunca mais fale comigo."},{"a":"leather","t":"Droga, essa foi quase."},{"a":"leather","t":"...Acho que vou precisar descobrir outro jeito de cuidar daquelas ovelhas."}]}]},{"id":"malady","name":"Enfermidade","chapters":[{"id":"malady_01","i":1,"title":"Escrito na Pedra","req":"malady:1","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"argon","t":"Missão concluída! Crianças perdidas; encontradas e resgatadas!"},{"a":"argon","t":"As Ruínas de Cronos realmente não são um lugar seguro para brincar."},{"a":"argon","t":"Acho melhor eu procurar uma saída também!"},{"a":"malady","t":"...Espero que os terríveis troubelins me deixem em paz hoje."},{"a":"argon","t":"Oi, moça! Você também está perdida?"},{"a":"malady","t":"Não... não se aproxime!"},{"a":"argon","t":"Hein?"},{"a":"argon_stone","t":"..."},{"a":"malady","t":"Se você olhar nos meus olhos, vai virar pedra. É a maldição da Medusa."},{"a":"malady","t":"Se bem que... você parece gentil."},{"a":"malady","t":"...Sinto muito."}]},{"id":"malady_02","i":2,"title":"Ele de Mármore","req":"malady:2","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"lilu","t":"*Hnng*... Ancião... Owen..."},{"a":"elderowen","t":"Lilu! O que você está fazendo, arrastando uma estátua!?"},{"a":"elderowen","t":"Uma estátua... do Argon!?"},{"a":"lilu","t":"Huff... Huff... Essa estátua É o Argon!"},{"a":"elderowen","t":"Ai, minha nossa. Foi petrificado?"},{"a":"lilu","t":"Acho que sim. Encontrei ele desse jeito nas Ruínas de Cronos."},{"a":"lilu","t":"Rudo me ajudou a carregá-lo em parte do caminho, ainda bem!"},{"a":"elderowen","t":"Que situação. Você consegue curá-lo?"},{"a":"lilu","t":"Provavelmente! Mas os ingredientes são raros, não vai ser fácil."},{"a":"lilu","t":"Vou reunir os moradores e comerciantes da cidade! Deixo o Argon sob seus cuidados!"},{"a":"elderowen","t":"É claro. Espero que não se importe em passar um tempo como enfeite de jardim, rapaz."},{"a":"argon_stone","t":"..."},{"a":"elderowen","t":"Ah, malditas pombas! Xô!"}]},{"id":"malady_03","i":3,"title":"Olho por Olho","req":"malady:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"lilu","t":"...Essa Videira Exuberante deve ser antiga o suficiente pra funcionar. Não sobraram muitas..."},{"a":"lilu","t":"Depois... Sangue de Medusa. Isso não vai ser fácil."},{"a":"malady","t":"Hm..."},{"a":"lilu","t":"Aah! Monstro!"},{"a":"malady","t":"...Você é amiga daquele humano que veio aqui?"},{"a":"lilu","t":"Argon? Espera, foi VOCÊ que fez aquilo?"},{"a":"lilu","t":"Bom, isso deixa tudo MUITO mais fácil. Por acaso eu preciso de um pouco de sangue de Medusa..."},{"a":"malady","t":"Não, por favor! Eu não quero fazer mal."},{"a":"lilu","t":"Até parece! Você o transformou em pedra!"},{"a":"malady","t":"... Peço desculpas. Eu fiquei assustada e nossos olhares se encontraram."},{"a":"malady","t":"Eu não sabia como reagir... Ninguém nunca foi gentil comigo antes."},{"a":"lilu","t":"... Caramba, você sofreu."},{"a":"malady","t":"Se precisa de sangue... eu posso dar."},{"a":"malady","t":"Em troca, por favor... me leve com você. Quero pedir desculpas a ele."},{"a":"lilu","t":"Tá bom. Não gosto disso, mas se eu virar pedra, duvido que o Donovan vá nos salvar."},{"a":"lilu","t":"Estou de olho em você. Agora você, não olha pra mim!"},{"a":"malady","t":"... Sim. Obrigada."}]},{"id":"malady_04","i":4,"title":"De Volta à Vida","req":"malady:4","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"lilu","t":"Tudo pronto! Essa poção deve funcionar. Splish Splash!"},{"a":"argon","t":"... Aaaah! Como é bom se alongar!"},{"a":"argon","t":"Espera, o que aconteceu?"},{"a":"lilu","t":"A Malady aqui transformou você em pedra por acidente e queria pedir desculpas."},{"a":"malady","t":"O-olá. Me perdoe. Eu não queria..."},{"a":"argon","t":"Ah, tá tudo bem! Me sinto ótimo! Só um pouco dolorido..."},{"a":"argon","t":"Você é a Malady? Meu nome é Argon, prazer!"},{"a":"argon","t":"Ei, sua bandana escorregou. Deixa que eu arrumo pra você!"},{"a":"lilu","t":"Argon! Não!"},{"a":"argon_stone","t":"..."},{"a":"lilu","t":"Argon... Vou ter que explicar o que são as Medusas pra ele..."},{"a":"malady","t":"Ah, não! Eu sinto muito!"},{"a":"lilu","t":"Imagina. Dessa vez a culpa é dele."},{"a":"malady","t":"E-estou pronta pra doar mais sangue..."},{"a":"lilu","t":"Não conheço bem a fisiologia das Medusas, mas é melhor esperar alguns dias antes de retirar sangue."},{"a":"lilu","t":"Enquanto isso fique aqui. Não é seguro andar por aí quando está fraca."},{"a":"lilu","t":"Embora, considerando seus... poderes, talvez seja melhor falar com o Ancião Owen primeiro..."},{"a":"malady","t":"... Sim."}]},{"id":"malady_05","i":5,"title":"Boas-vindas ao Lar","req":"malady:5","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"lilu","t":"Ancião Owen, estamos de volta!"},{"a":"elderowen","t":"Argon foi curado? Que notícia excelente!"},{"a":"lilu","t":"Ainda... não. Mas..."},{"a":"malady","t":"..."},{"a":"elderowen","t":"P-pela Deusa! Uma Medusa, aqui!?"},{"a":"lilu","t":"Essa é a Malady. Ela me ajudou a curar o Argon!"},{"a":"lilu","t":"Ela vai ter que ficar aqui por alguns dias pra gente poder curá-lo... de novo."},{"a":"elderowen","t":"Entendi... Eu certamente não sinto nenhuma maldade em você. Perdoe minha reação, Malady."},{"a":"malady","t":"Graças à minha maldição... Todos me odeiam, até mesmo outros monstros. Já me acostumei."},{"a":"elderowen","t":"As portas da cidade estão sempre abertas para quem deseja trabalhar pelo bem de todos."},{"a":"malady","t":"... É mesmo?"},{"a":"elderowen","t":"Desde que você fique com os olhos cobertos, não vejo mal nenhum."},{"a":"elderowen","t":"Malady... Te desejo mais sorte aqui do que entre os monstros."},{"a":"malady","t":"Obrigada... Nunca fui bem-vinda em lugar algum antes..."},{"a":"elderowen","t":"Você deveria falar com o comerciante. Sempre há trabalho disponível para jovens como você."},{"a":"lilu","t":"Isso! Você pode participar de missões com a gente!"},{"a":"malady","t":"Eu vou... Obrigada, Lilu e Owen."}]}]},{"id":"hemma","name":"Hemma","chapters":[{"id":"hemma_01","i":1,"title":"Sombra Ameaçadora","req":"hemma:1","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"hemma","t":"... E então o Troubelin caiu, mas não sem antes atacar alguns de meus companheiros."},{"a":"hemma","t":"Cuide para que sejam todos curados."},{"a":"priest","t":"Mas é claro. Eu cuidarei das feridas imediatamente."},{"a":"lilu","t":"Olá! Ouvi dizer que há uma nova conjuradora na cidade."},{"a":"lilu","t":"Eu sou a Lilu! É um prazer te conhecer!"},{"a":"hemma","t":"Você está certa, jovem Lilu. Nosso nome é Hemma. "},{"a":"lilu","t":"...\"Nosso\"?"},{"a":"hemma","t":"...Sim. A necromancia cobra um preço de seus praticantes..."},{"a":"hemma","t":"Parte de você fica além do Véu enquanto outras coisas cruzam os limites..."},{"a":"hemma","t":"Esses poderes... nos mudaram. Para melhor, é claro."},{"a":"lilu","t":"Você disse necromancia? Isso não é... perigoso?"},{"a":"hemma","t":"Altamente. Mas não ficamos mais satisfeitas com apenas alguns truques."},{"a":"hemma","t":"Agora, se nos dá licença, precisamos estar em outro lugar. Adeus."},{"a":"lilu","t":"Uma necromante... Essa é uma magia das sombras, Pollux! É a primeira vez que eu vejo uma praticante de verdade!"},{"a":"lilu","t":"Ela não parecia tão má... Parecia?"}]},{"id":"hemma_02","i":2,"title":"Custe o que Custar","req":"hemma:2","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"elderowen","t":"Uma necromante...?"},{"a":"elderowen","t":"Não sei o que pensar disso tudo..."},{"a":"hemma","t":"Você tem razão em se preocupar. A necromancia é uma arte perigosa que consumiria seres menores..."},{"a":"hemma","t":"Mas não somos menores de forma alguma."},{"a":"elderowen","t":"E quanto aos aventureiros que andam com você? Você não os drena para fortalecer seus feitiços?"},{"a":"hemma","t":"Apenas se eles permitirem. Os efeitos não são permanentes."},{"a":"hemma","t":"E nós os pagamos bem pelos serviços."},{"a":"elderowen","t":"Acredito que vocês estão fazendo algo de bom, no fim das contas..."},{"a":"elderowen","t":"Muito bem. Acredito que podem ser Campeãs oficiais de nossa cidade."},{"a":"hemma","t":"Não precisamos de sua aprovação... mas agradecemos."},{"a":"elderowen","t":"Então, o que as trouxe para nossa cidade?"},{"a":"hemma","t":"..."},{"a":"hemma","t":"Apenas buscamos conhecimento e poder. "},{"a":"hemma","t":"Há... uma tarefa que devemos cumprir."},{"a":"elderowen","t":"Isso é muito vago..."},{"a":"hemma","t":"E continuará a ser. Adeus."},{"a":"elderowen","t":"..."},{"a":"elderowen","t":"Há tanta tristeza naqueles olhos..."}]},{"id":"hemma_03","i":3,"title":"O inimigo interior","req":"hemma:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"herbalist","t":"... Raízes Vivas ainda verdes e um tanto de Ectoplasma Sinistro. Mais alguma coisa?"},{"a":"hemma","t":"Isso é tudo. Visitaremos o comerciante para pegar o resto."},{"a":"herbalist","t":"Obrigada! Volte sempre!"},{"a":"hemma","t":"<c4>...Não esqueça as Garras Cruéis.</c4>"},{"a":"hemma","t":"Ah, sim. Um par de Garras Cruéis, por favor."},{"a":"herbalist","t":"... O QUE foi isso?"},{"a":"hemma","t":"Não dê atenção. Um passageiro, só isso."},{"a":"hemma","t":"<c4>Me-deixa-sair-quero-sair-me-deixa-sair.</c4>"},{"a":"hemma","t":"Ugh. Acalme-se."},{"a":"hemma","t":"Fique com o troco. Adeus."},{"a":"herbalist","t":"...Obrigada pela gorjeta... e pelos pesadelos."}]},{"id":"hemma_a","i":3,"title":"Entre Imortais","req":"hemma:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fichas da fortuna"},"side":true,"lines":[{"a":"donovan","t":"Raízes Vivas verdes? Escolha interessante."},{"a":"hemma","t":"Vai usar em quê?"},{"a":"donovan","t":"Raízes Vivas são reagentes fortes para muitas magias relacionadas à juventude e longevidade."},{"a":"donovan","t":"Você é também é Alquimista? Está em uma missão por longevidade, então?"},{"a":"hemma","t":"...Você pergunta a idade de uma dama? Que... descabido."},{"a":"hemma","t":"Não somos alquimistas. O sacrifício de sangue é muito mais eficaz."},{"a":"donovan","t":"Ah, a necromancia! Um campo respeitável, mas incompreendido."},{"a":"hemma","t":"E sobre a nossa idade... paramos de contar já faz um tempo."},{"a":"donovan","t":"Eu sei como é. Décadas passam num piscar de olhos depois de alguns séculos!"},{"a":"donovan","t":"Bate uma solidão no meio desses insetos, não é?"},{"a":"hemma","t":"Não sentimos solidão. Seria melhor se você não se metesse em assuntos de uma necromante."},{"a":"donovan","t":"Claro. Não quis me intrometer. Adeus!"},{"a":"donovan","t":"Necromante esquisita... já nos conhecemos?"},{"a":"donovan","t":"...Fairlyn?"}]},{"id":"hemma_04","i":4,"title":"Exorcismo","req":"hemma:4","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"lilu","t":"Não se preocupe, Hemma. Eu tô aqui! E trouxe a Freyja!"},{"a":"priest","t":"Hemma, não é? Relaxe. Deixe o exorcismo passar por você..."},{"a":"hemma","t":"Não lembramos de pedir sua ajuda."},{"a":"hemma","t":"<c4>Aceitem, crianças. Daqui ninguém me tira.</c4>"},{"a":"lilu","t":"Aaaah! Está assumindo o controle! Rápido, Freyja!"},{"a":"priest","t":"Não... consigo! Tem alguma coisa impedindo minhas preces..."},{"a":"hemma","t":"Somos nós. Pare com isso."},{"a":"priest","t":"Vocês... estão aceitando esse espírito maligno de propósito?"},{"a":"hemma","t":"Ele enlouqueceu com o tempo, admito."},{"a":"hemma","t":"<c4>Eu que sou a vítima aqui! Me deixem sair!</c4>"},{"a":"hemma","t":"Ugh. Ele é mais rude que maligno, pode acreditar."},{"a":"hemma","t":"Esse assunto não lhe diz respeito. Não se envolva, Freyja."},{"a":"priest","t":"Esses necromantes... sempre brincando com poderes que não entendem!"},{"a":"lilu","t":"Tudo bem, Freyja! Com certeza ela sabe o que está fazendo!"},{"a":"lilu","t":"...Né?"}]},{"id":"hemma_05","i":5,"title":"Aquela com Duas Mentes","req":"hemma:5","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"hemma","t":"<c4>Olha só quem está mostrando as asinhas. Vai sair da cidade?</c4>"},{"a":"hemma","t":"Isso é culpa SUA. Se ficasse em silêncio, tudo seria mais fácil."},{"a":"hemma","t":"Mesmo assim, ainda não estamos indo embora. Essa é uma cidade promissora."},{"a":"hemma","t":"<c4>Tá bem. Mas que tal me deixar sair pelo menos uma vez?</c4>"},{"a":"hemma","t":"Claro que não. Já é difícil controlar você desse jeito."},{"a":"hemma","t":"<c4>Me-deixa-sair-quero-sair-me-deixa-sair.</c4>"},{"a":"hemma","t":"Isso é para o seu bem, Claud."},{"a":"hemma","t":"...Lembre-se disso."}]},{"id":"hemma_06","i":6,"title":"Legado de Mentiras","req":"hemma:6","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"lilu","t":"Fairlyn!"},{"a":"hemma","t":"Pois não?"},{"a":"lilu","t":"Eu sabia! Hemma é um nome falso! Você é o monstro, Fairlyn!"},{"a":"hemma","t":"Minha nossa, mas que diabinha engenhosa temos aqui."},{"a":"hemma","t":"É verdade. Parece que você andou estudando."},{"a":"hemma","t":"Talvez você também tenha ouvido falar de Ariel, a Louca? Ou de Astrid, a Caída?"},{"a":"lilu","t":"Já ouvi falar delas... mas elas sumiram há décadas! Não podem ser..."},{"a":"hemma","t":"Todas nós, é claro. Infelizmente, enfrentamos muitas perseguições, e precisamos trocar de nomes..."},{"a":"lilu","t":"Você é um monstro! Alguém precisa deter você!"},{"a":"hemma","t":"E como pretende fazer isso? \"Hemma\" é inocente. Quem acreditaria nesta loucura que você contou?"},{"a":"hemma","t":"A menos, é claro, que você queira me deter sozinha..."},{"a":"lilu","t":"Hunf!"}]},{"id":"hemma_07","i":7,"title":"Laço de Alma","req":"hemma:7","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"hemma","t":"Ainda está tentando fugir?"},{"a":"lilu","t":"Eu vou ficar de olho em você. E nos seus monólogos suspeitos..."},{"a":"hemma","t":"Ah, sim. Diga olá a Claud, nosso marido. Ele já teve dias melhores."},{"a":"hemma","t":"<c4>Quero sair!</c4>"},{"a":"lilu","t":"O que aconteceu com ele?"},{"a":"hemma","t":"Um acidente necromântico terrível. Um erro tolo o deixou à beira da morte."},{"a":"hemma","t":"Considerando os nossos pecados na vida, o pós-vida é uma ideia aterrorizante para nós, necromantes..."},{"a":"hemma","t":"Incapaz de salvar o corpo dele, fizemos o possível... e salvamos sua alma."},{"a":"lilu","t":"Um Laço de Alma? Esse feitiço exige anos de pesquisa para criar um receptáculo adequado..."},{"a":"hemma","t":"De fato. Dadas as circunstâncias, improvisamos."},{"a":"lilu","t":"Improvisaram? Está dizendo que... vinculou a alma do Claud à sua?!"},{"a":"lilu","t":"Um corpo não consegue aguentar duas almas! Isso causaria..."},{"a":"hemma","t":"Uma dor capaz de destruir a mente. Insanidade. Pior do que tudo o que você pode imaginar."},{"a":"lilu","t":"Hemma... Por quê? Como?"},{"a":"hemma","t":"É simples, pequena Lilu. Falhar... não é uma opção."}]},{"id":"hemma_08","i":8,"title":"A Recompensa do Século","req":"hemma:8","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"lilu","t":"É poderosa demais para exorcizar... talvez a alma esteja vinculada a outra coisa..."},{"a":"hemma","t":"Você está cooperando até demais. Por acaso se interessou pela necromancia?"},{"a":"lilu","t":"Não! Eu odeio você e tudo o que fez!"},{"a":"lilu","t":"... Pelo que eu sei, se esse Claud se libertar, todo mundo pode se meter em grandes problemas."},{"a":"lilu","t":"Eu estou ajudando você a arrumar essa bagunça, só isso!"},{"a":"hemma","t":"Um propósito nobre. Mas como uma simples criança seria capaz de ajudar?"},{"a":"lilu","t":"Preparar um receptáculo apropriado exigiria décadas de pesquisas e materiais..."},{"a":"hemma","t":"Isso não será um problema. Contemple..."},{"a":"lilu","t":"...! Como você conseguiu tudo isso? Tem até Diamantes Pretos!"},{"a":"hemma","t":"Não desperdicei minhas últimas décadas. O tempo urge."},{"a":"hemma","t":"O que resta é o local adequado para a execução do ritual. Tememos que tal lugar não exista."},{"a":"lilu","t":"Tá. A alma precisa de uma ligação espiritual com o lugar, senão o vínculo não vai funcionar."},{"a":"hemma","t":"<c4>Ou vocês podiam só deixar o bom e velho Claud Favius sair! Ele vai fazer muitos amigos!</c4>"},{"a":"lilu","t":"Espera... Você disse Favius?"}]},{"id":"hemma_09","i":9,"title":"O Castelo Assombrado","req":"hemma:9","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"hemma","t":"Mas que lugar assombrado maravilhoso."},{"a":"lilu","t":"Esse lugar é o ó. Ninguém com a cabeça no lugar vem até aqui."},{"a":"lilu","t":"Mas o mais importante, de acordo com a minha pesquisa..."},{"a":"lilu","t":"É que essa era a propriedade de um rei louco da família Favius, séculos atrás."},{"a":"lilu","t":"Talvez Claud seja um parente distante. Tomara que ele não tenha nenhuma ligação com a ruína do reino..."},{"a":"hemma","t":"Podemos sentir. Temos uma ligação com este lugar. É isto."},{"a":"hemma","t":"Temos uma grande dívida com você, Lilu. Mas agora você deve nos deixar a sós."},{"a":"lilu","t":"Hemma... Boa sorte."}]},{"id":"hemma_10","i":10,"title":"Até que a morte nos separe","req":"hemma:10","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"hemma","t":"Um lugar sombrio e recluso, cheio de energia necromântica..."},{"a":"hemma","t":"Há quanto tempo buscamos um lugar assim?"},{"a":"hemma","t":"Agora devemos encontrar um receptáculo apropriado..."},{"a":"hemma","t":"Não precisa falar. Sabemos exatamente o que quer."},{"a":"Castle_Boss","t":"..."},{"a":"hemma","t":"A armadura do próprio rei louco, ligada a este lugar para sempre."},{"a":"hemma","t":"<c1>Laço de Alma!</c1>"},{"a":"Castle_Boss","t":"..."},{"a":"hemma","t":"Argh... Nos sentimos... ou eu me sinto...?"},{"a":"hemma","t":"Eu havia esquecido como é a sensação de solidão..."},{"a":"hemma","t":"Eu sofri uma eternidade para salvar você, querido. Porque eu sabia que você teria feito a mesma coisa por mim."},{"a":"hemma","t":"Aventureiros valentes virão, com certeza. Enfrente-os e, através da carnificina, cure sua existência tortuosa."},{"a":"Castle_Boss","t":"..."},{"a":"hemma","t":"Adeus, meu amado. Mas apenas com a morte seremos separados."}]},{"id":"hemma_epilogue","i":11,"title":"Epílogo","req":"hemma:11","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"Castle_Boss","t":"<c4>TOLOS!!! COMO OUSAM PISAR EM MINHAS TERRAS?</c4>"},{"a":"sia","t":"Que inimigo terrível!"},{"a":"Castle_Boss","t":"<c4>MUAHAHAHA! RELES MORTAIS!</c4>"},{"a":"argon","t":"Lady Sia! Rudo! Precisamos recuar!"},{"a":"rudo","t":"Nunca! Eu não vou ceder um centímetro sequer!"},{"a":"yami","t":"Encontrei uma saída. Rápido!"},{"a":"rudo","t":"Ah! Eu vou voltar, sua lata de lixo gigante! Ouviu?"},{"a":"Castle_Boss","t":"<c4>VOLTE QUANDO FOR UM DESAFIO DE VERDADE!</c4>"},{"a":"Castle_Boss","t":"<c4>DIGA AOS SEUS MAIORES HERÓIS QUE O REI TIRANO AGUARDA!</c4>"}]}]},{"id":"lilu","name":"Lilu","chapters":[{"id":"lilu_01","i":1,"title":"Aprendiz precoce","req":"lilu:1","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"lilu","t":"E então, Pollux? O que você acha desse novo feitiço? Perfeito, certo?"},{"a":"lilu","t":"Sim, desta vez vamos acertar em cheio!"},{"a":"herbalist","t":"Bom dia, Lilu. Está aqui pelo carregamento semanal de raízes vivas?"},{"a":"lilu","t":"Sim, obrigada Maribel!"},{"a":"herbalist","t":"Seu pedido foi grande essa semana! O que seu mestre fará com tudo isso?"},{"a":"lilu","t":"Para falar a verdade, metade é para mim. Eu estou estudando alguns feitiços importantes!"},{"a":"herbalist","t":"É mesmo? De que tipo?"},{"a":"lilu","t":"Feitiços de cura! Eu passei toda a semana passada curando cortes e ferimentos na sala de treinamento!"},{"a":"herbalist","t":"Certo, tenho certeza de que os heróis estão felizes em ter você por perto."},{"a":"herbalist","t":"...E Argon também!"},{"a":"lilu","t":"...!"},{"a":"lilu","t":"E-eu preciso ir! Obrigada!"}]},{"id":"lilu_02","i":2,"title":"Augúrios sinistros","req":"lilu:2","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"lilu","t":"Aqui está, Mestre Grimar. As raízes vivas desta semana."},{"a":"wizard","t":"Obrigado, Lola. Aqui está o dever de casa de hoje."},{"a":"lilu","t":"Ah! Um tomo mágico! É sobre a cura!?"},{"a":"lilu","t":"\"O Manual de Maldições do Malfeitor\"...?"},{"a":"lilu","t":"Este livro é avançado demais! Tem uma seção inteira sobre maldições!"},{"a":"wizard","t":"...Maldições?"},{"a":"wizard","t":"Hmm... maldições...?"},{"a":"lilu","t":"Mestre?"},{"a":"wizard","t":"35 anos atrás, neste dia... eu...!"},{"a":"lilu","t":"Mestre Grimar!?"},{"a":"wizard","t":"...Eu esqueci. E quem é você?"},{"a":"lilu","t":"...Lilu, sua aprendiz. Ou Lola, às vezes..."},{"a":"lilu","t":"Ok, deixa pra lá. Vou estudar este livro. Obrigada, Grim."}]},{"id":"lilu_03","i":3,"title":"Mente confusa","req":"lilu:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"lilu","t":"...Adicione uma pitada de pó de prata e... pronto!"},{"a":"lilu","t":"Olha como brilha! Nada mal, né Pollux?"},{"a":"lilu","t":"Se o Manual de Maldições do Malfeitor estiver correto, esta poção deverá..."},{"a":"wizard","t":"Lola, que barulho todo é esse? Estou tentando dormir aqui!"},{"a":"lilu","t":"Mestre Grimar! Graças ao seu livro, preparei uma poção muito avançada! Ela deve..."},{"a":"wizard","t":"Você fez o quê?"},{"a":"wizard","t":"Bem, então dê ela para mim! Vamos experimentá-la!"},{"a":"wizard","t":"..."},{"a":"lilu","t":"Mestre Grimar?"},{"a":"wizard","t":"Lilu! E-eu pre-ci-ci-so me li-li-bertar! Li-liberte-me dessa me-mente estúpida e patética!"},{"a":"lilu","t":"Me-mestre Grimar! Você está bem?"},{"a":"wizard","t":"..."},{"a":"wizard","t":"*Arroto* Tem sabor de fruta!"},{"a":"wizard","t":"Nada mal, Lola. Agora, de volta às suas tarefas."},{"a":"lilu","t":"...Isso não foi NADA normal."}]},{"id":"lilu_a","i":3,"title":"Acumulante das Eras","req":"lilu:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fichas da fortuna"},"side":true,"lines":[{"a":"lilu","t":"Grimar, você não me disse que tinha outro <c1>Livro da Coleção</c1>!"},{"a":"wizard","t":"<c1>Livro da Coleção</c1>...? Isso me lembra de alguma coisa..."},{"a":"lilu","t":"Opa! Esse aqui está cheio de informações! <c1>Dâmocles</c1>... <c1>Cidadela Âmbar</c1>..."},{"a":"lilu","t":"<c1>Grã-varinha de Grimar</c1>...? Você escolheu o nome dessa?"},{"a":"lilu","t":"São tantas páginas! Você deve ser um colecionador e tanto!"},{"a":"sundragon","t":"Com certeza ele era!"},{"a":"wizard","t":"É você, Soldra, velho amigo?"},{"a":"lilu","t":"Uau! Vocês se conhecem?"},{"a":"sundragon","t":"De fato. O jovem Grimar era completamente apaixonado pelo Livro da Coleção."},{"a":"sundragon","t":"Acredito que isso deu a ele um título nobre entre os colegas humanos...\"Nerd\", não era mesmo?"},{"a":"lilu","t":"Ai..."},{"a":"sundragon","t":"Nos encontramos durante a missão dele por itens raros e criamos o <c1>Caldeirão de Fusões</c1> juntos."},{"a":"sundragon","t":"Ele passou dias e noites fazendo fusões de centenas de itens... e ainda mais durante a lua cheia!"},{"a":"lilu","t":"Tanto esforço... e ele ainda não completou a coleção!"},{"a":"lilu","t":"Eu juro que vou te curar, Mestre Grimar! Você precisa terminar o trabalho da sua vida!"},{"a":"sundragon","t":"O tempo é mesmo cruel para os humanos. Desejo sorte em sua missão, criança."}]},{"id":"lilu_04","i":4,"title":"Fim da linhagem","req":"sia:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"lilu","t":"Tem algo de errado com o Mestre Grimar..."},{"a":"lilu","t":"Sua voz era como se alguém estivesse falando de dentro dele!"},{"a":"lilu","t":"Talvez estejamos lidando com um feitiço de transmutação complexo?"},{"a":"lilu","t":"Ou talvez até...."},{"a":"leather","t":"Ei, Lilu! Algo deu errado no banquete do rei!"},{"a":"lilu","t":"Tamas? O que foi?"},{"a":"leather","t":"Algo sobre um invasor no castelo. Bem assustador!"},{"a":"lilu","t":"Um invasor...! Ah não, este é o primeiro dia de Argon como cavaleiro!"},{"a":"lilu","t":"Obrigada Tamas, preciso ir!"},{"a":"lilu","t":"Ah não...! O que está acontecendo aqui!?"},{"a":"lilu","t":"Argon, cadê você!?"},{"a":"king","t":"Aaargh..."},{"a":"lilu","t":"REI REINHOLD!? Você está bem!?"},{"a":"king","t":"Aahh... Minha vida preciosa... se esvaindo..."},{"a":"lilu","t":"Isso não é nada bom...!"},{"a":"lilu","t":"Concentre-se, Lilu! Lembre-se do treinamento do Sábio!"},{"a":"lilu","t":"Rei Reinhold! Fique parado! <c1>Curar</c1>!"},{"a":"king","t":"Não adianta... por favor... preserve meu lindo cadáver..."},{"a":"lilu","t":"Nenhum efeito..."},{"a":"lilu","t":"Ah não... será que foi um... veneno?"},{"a":"lilu","t":"...Assim como meus pais...! Eu não vou fracassar desta vez! Não posso!"},{"a":"lilu","t":"<c1>Purificação superior de veneno!</c1>"},{"a":"king","t":"...Aaaah... Hein?"},{"a":"lilu","t":"Rei Reinhold! Como está se sentindo?"},{"a":"lilu","t":"Espere um minuto... Esse copo protegeu você daquela shuriken! Você não estava ferido!"},{"a":"king","t":"Ah! É mesmo? Acho que posso ter exagerado um pouco."},{"a":"king","t":"A morte de um monarca é sempre algo dramático, afinal de contas."},{"a":"lilu","t":"Aff! Reinhold!"}]},{"id":"lilu_05","i":5,"title":"Escolha seu veneno","req":"lilu:5","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"lilu","t":"Ugh... Essa foi por pouco... eu acho."},{"a":"lilu","t":"Se Reinhold foi mesmo envenenado... Eu não teria como salvar ele."},{"a":"lilu","t":"Preciso redirecionar meus esforços. E garantir que ninguém sofra uma perda como a minha..."},{"a":"lilu","t":"Senhorita Sia!"},{"a":"sia","t":"Ah, a estrela do momento! Um cavaleiro foi enviado para cuidar do intruso. Pode relaxar."},{"a":"lilu","t":"(Um cavaleiro? Boa sorte, Argon!)"},{"a":"sia","t":"Obrigado por... salvar o nosso rei, apesar das circunstâncias."},{"a":"lilu","t":"Não foi nada! Mas, se isso acontecesse de novo, não sei se eu poderia ajudar..."},{"a":"lilu","t":"Senhorita Sia, você entende de venenos?"},{"a":"sia","t":"É claro. O acônito é um assassino extremamente eficiente."},{"a":"sia","t":"Mas a ricina é um dos meus favoritos. Silenciosa, mortal e fácil de encontrar..."},{"a":"lilu","t":"Hã... e isso tem cura?"},{"a":"sia","t":"Ah. Na verdade, nunca parei pra pensar nisso."},{"a":"lilu","t":"...Esqueça que eu perguntei."}]},{"id":"lilu_06","i":6,"title":"Mestre e estudante","req":"lilu:6","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"lilu","t":"Voltei, mestre Grimar!"},{"a":"wizard","t":"Bem-vinda de volta, Lola."},{"a":"lilu","t":"Tentaram matar o rei! Você acredita nisso?"},{"a":"wizard","t":"É mesmo..."},{"a":"lilu","t":"Um assassino surgiu do nada e atacou ele com um shuriken!"},{"a":"lilu","t":"E depois eu corri pra ajudar enquanto ele agonizava no chão..."},{"a":"wizard","t":"Hã... quem é você, mesmo?"},{"a":"lilu","t":"Ah, sim. A sua doença... Preciso retomar isso!"},{"a":"lilu","t":"Pode ser veneno, também..."},{"a":"lilu","t":"Vejamos... Grimar é velhão..."},{"a":"lilu","t":"O que acha, Pollux?"},{"a":"lilu","t":"Acho que a gente devia perguntar pela cidade!"},{"a":"lilu","t":"Talvez algum dos antigos residentes lembre de como era o jovem Grimar."}]},{"id":"lilu_07","i":7,"title":"Conhecimento ancestral","req":"lilu:7","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"lilu","t":"Mestre Theodore!"},{"a":"master","t":"Se não é Lilu! Como posso ajudar hoje?"},{"a":"lilu","t":"Será que você poderia me falar sobre Grimar, de quando ele era jovem..."},{"a":"lilu","t":"...Já que você é... velho e tal."},{"a":"master","t":"Ho ho ho! É claro, claro."},{"a":"master","t":"O velho Grimar sempre foi meio... excêntrico."},{"a":"master","t":"Mas quando eu era um jovenzinho, lembro que ele era muito mais astuto. Meu rival no xadrez, até."},{"a":"master","t":"Mas depois daquela jornada às Ruínas de Cronos... ele ficou meio estranho, agora que parei para pensar."},{"a":"lilu","t":"As Ruínas de Cronos! Que lugar perigoso!"},{"a":"lilu","t":"...Uma civilização inteira reduzida a ruínas enquanto investigava a magia do tempo..."},{"a":"lilu","t":"Aquele lugar é cheio de anomalias mágicas! O que Grimar iria querer num lugar como esse?"},{"a":"lilu","t":"Tem razão, Pollux. Essa é a nossa única pista. Vamos ter que investigar!"},{"a":"lilu","t":"Mas vamos precisar de uma escolta... O que acha de falar com Argon...?"},{"a":"lilu","t":"Não! E se um vórtice temporal aparecer de repente e deixar ele velho? Ou como o Grimar..."},{"a":"lilu","t":"...Só consigo pensar em mais uma pessoa para nos ajudar..."},{"a":"lilu","t":"Não vai ser fácil, Pollux! Mas temos que tentar!"},{"a":"lilu","t":"Valeu, Theodore! Você ajudou muito!"},{"a":"master","t":"Sem problema, Lilu! Até a próxima!"},{"a":"master","t":"..."},{"a":"master","t":"...Até onde vai a esperteza daquela coruja...?"}]},{"id":"lilu_08","i":8,"title":"Causa em Comum","req":"lilu:8","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"lilu","t":"Senhor Rudo, por favor! Não vá embora, preciso falar com você!"},{"a":"rudo","t":"Esqueça, criança, não quero ouvir."},{"a":"rudo","t":"Você e sua coruja podem ir brincar em outro lugar!"},{"a":"lilu","t":"Eu sei que não gosta de conjuradores... mas preciso mesmo da sua ajuda!"},{"a":"lilu","t":"Preciso ir até as profundezas das Ruínas de Cronos, mas não posso ir sozinha! "},{"a":"rudo","t":"Por que não vai falar com aquele tal de Argon, o cavaleiro de armadura brilhante?"},{"a":"lilu","t":"Ele... está ocupado com outra coisa agora..."},{"a":"lilu","t":"Então acho que não adianta pedir ajuda a você..."},{"a":"rudo","t":"Pode apostar, criança."},{"a":"tavern","t":"É uma pena, tesouro."},{"a":"tavern","t":"Ouvi dizer que o Senhor dos Ciclopes das Ruínas de Cronos nunca foi derrotado..."},{"a":"tavern","t":"Seria preciso um guerreiro muito habilidoso para escoltar a Lilu por aquelas ruínas!"},{"a":"rudo","t":"... Você disse que ele nunca foi derrotado?"},{"a":"rudo","t":"Tudo bem. Eu aceito. Quantas coisas eu vou precisar quebrar?"},{"a":"lilu","t":"Muitas, tenho certeza!"},{"a":"lilu","t":"Preciso encontrar a fonte do fluxo temporal que está emanando de vários cristais e isol..."},{"a":"rudo","t":"Vá direto para a parte de quebrar coisas."},{"a":"lilu","t":"...Tem monstros e cristais mágicos para quebrar."},{"a":"rudo","t":"Muito bem, combinado. Você me deve uma."},{"a":"lilu","t":"Fantástico! Muito obrigada, senhor Rudo!"},{"a":"rudo","t":"Agradeça depois da viagem, criança. Não vai ser moleza."},{"a":"lilu","t":"Eu estarei lá para te curar, se encontrar monstros demais!"},{"a":"rudo","t":"Hunf. Acho que não vai precisar."},{"a":"lilu","t":"E muito obrigado, Naya!"},{"a":"tavern","t":"De nada, tesouro."}]},{"id":"lilu_09","i":9,"title":"Mundo Espelhado","req":"lilu:9","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"rudo","t":"Eu vou cuidar do Ciclope para abrir caminho!"},{"a":"rudo","t":"Vem aqui, Ciclobeso! Eu trouxe aveia pra você!"},{"a":"lilu","t":"Entendido! Boa sorte!"},{"a":"lilu","t":"Esta é... a Câmara do Tempo. E, de acordo com a minha pesquisa..."},{"a":"lilu","t":"Este poço deve estar conectado a uma linha do tempo fragmentada!"},{"a":"lilu","t":"Um universo paralelo no qual a Cidade Cronos permanece próspera..."},{"a":"lilu","t":"Veja, Pollux! Dá pra ver alguma coisa ao olhar pra essa água!..."},{"a":"lilu","t":"Parece que as pessoas de Cronos levam uma vida normal em alguma outra dimensão..."},{"a":"lilu","t":"Ei... não parece que esse cara tá acenando pra nós?"},{"a":"lilu","t":"Ele é muito parecido com o... Grimar?!"}]},{"id":"lilu_10a","i":10,"title":"Maldição dos Anos Eternos","req":"lilu:10","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"lilu","t":"Grimar!!! Beba isto!"},{"a":"wizard","t":"Hum? Algo nisto me parece... familiar."},{"a":"lilu","t":"É um remédio especial preparado com Água de Cronos..."},{"a":"wizard","t":"... Temperado e estabilizado com Tramas do Destino...?"},{"a":"lilu","t":"... e condensado em forma material com Ectoplasma destilado."},{"a":"wizard","t":"E com uma pitada de Coral Profundo, pra dar um gostinho melhor!"},{"a":"wizard","t":"Que trabalho espetacular, Lilu. Como mestre, eu não poderia estar mais orgulhoso."},{"a":"lilu","t":"G-grimar... Você voltou ao normal! Funcionou!"},{"a":"wizard","t":"Que experiência peculiar... É como se a minha mente tivesse aclarado..."},{"a":"lilu","t":"Tenho uma vaga ideia sobre o funcionamento da poção, mas... há algo que não faz sentido."},{"a":"lilu","t":"Nós te vimos no poço! Na linha do tempo fragmentada!"},{"a":"wizard","t":"Ora, ora! É mesmo? Tenho uma teoria quanto a isso..."},{"a":"wizard","t":"Pollux, faria a gentileza de buscar o velho Owen? Receio que haja muito a ser explicado..."}]},{"id":"lilu_10b","i":11,"title":"Teorema da Quebra do Tempo","req":"lilu:10","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"elderowen","t":"É deveras uma história fascinante, velho amigo!"},{"a":"lilu","t":"Ainda mal consigo acreditar... Grimar é um sobrevivente da Cidade Cronos?"},{"a":"wizard","t":"Após o Feitiço do Tempo não sair como planejado, a cidade inteira foi lançada em outra linha do tempo."},{"a":"elderowen","t":"Eu me lembro daquele dia como se fosse ontem. Uma cidade inteira desaparecendo num piscar de olhos!"},{"a":"elderowen","t":"Só o que encontramos nas ruínas foi uma criança, vagando como se estivesse perdida..."},{"a":"lilu","t":"Grimar, certo? É difícil imaginar vocês dois como crianças..."},{"a":"elderowen","t":"Ho ho! Nós rapidamente nos tornamos amigos, não foi?"},{"a":"wizard","t":"Certamente. Eu estudei para me tornar feiticeiro e poder avaliar este estranho evento por conta própria."},{"a":"wizard","t":"Se o que Lilu viu for real, acredito que exista outro Grimar."},{"a":"lilu","t":"O outro Grimar que vimos... você ainda existe na outra linha do tempo?!"},{"a":"wizard","t":"Aparentemente, sim. A princípio não houve consequências, mas..."},{"a":"wizard","t":"À medida que os Grimars cresciam, nossas personalidades e experiências de vida começaram a se distinguir."},{"a":"lilu","t":"E esse paradoxo mágico crescente começou a afetar a sua mente..."},{"a":"lilu","t":"Entendi! Beber uma poção das Ruínas de Cronos deve te conectar novamente à outra linha do tempo!"},{"a":"wizard","t":"Essa é a minha teoria. Tenho certeza de que o outro Grimar também concorda."},{"a":"lilu","t":"Nossa... é muita coisa. Acho que vou precisar de mais tempo pra pensar nisso... Você vem comigo, Pollux?"},{"a":"elderowen","t":"Quanto a nós, velho Grim, parece que o nosso tempo já passou mesmo!"},{"a":"wizard","t":"Fale por si, velhote! Eu me sinto mais jovem do que nunca!"}]},{"id":"lilu_epilogue","i":12,"title":"Epílogo","req":"lilu:11","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"lilu","t":"Olá, Grimar! Aqui está uma nova receita. Deve durar um pouco mais!"},{"a":"wizard","t":"Um avanço notável! Seus pais ficariam orgulhosos."},{"a":"lilu","t":"... Se ao menos eu tivesse estudado alquimia mais cedo..."},{"a":"wizard","t":"Também me sinto assim. Se eu estivesse em total controle das minhas funções, talvez..."},{"a":"lilu","t":"... Tudo bem. Decidi focar no futuro. Para me aperfeiçoar e salvar os outros desse destino."},{"a":"lilu","t":"... Sei que isso é o que os meus pais gostariam."},{"a":"wizard","t":"Você cresceu tanto... mal posso te reconhecer."},{"a":"wizard","t":"Aliás... quem é você, mesmo?"},{"a":"lilu","t":"Ah, não! O efeito já está passando! É melhor eu..."},{"a":"wizard","t":"Ho ho ho! Só estava brincando. Estou otimista quanto a esta receita."},{"a":"wizard","t":"Vejamos... enquanto minha mente está lúcida, que tal aprender magia?"},{"a":"wizard","t":"O mestre ainda tem alguns truques na manga!"},{"a":"lilu","t":"Ah! Que tal Polimorfia? Mal posso esperar!"}]}]},{"id":"polonia","name":"Polônia","chapters":[{"id":"polonia_01","i":1,"title":"Marinheiro de água doce admirável","req":"polonia:1","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"polonia","t":"Yo ho ho! Marinheiros de água doce!"},{"a":"polonia","t":"Cê já sonhou com histórias de espadachins e pirataria em alto mar?"},{"a":"polonia","t":"Eu, Capitã Polônia Del Monte, tô atrás de recrutas pro meu navio!"},{"a":"polonia","t":"Como filha do lendário pirata Baross Del Monte, eu prometo uma vida de tesouros e aventura!"},{"a":"argon","t":"Capitã Polônia, é?"},{"a":"polonia","t":"Isso. Tem interesse? Um garanhão como você seria muito bem-vindo."},{"a":"argon","t":"G-garanhão?!"},{"a":"argon","t":"Hã, na verdade... Eu sou Argon, cavaleiro em treinamento!"},{"a":"argon","t":"Pirataria é ilegal, então... por favor, renda-se e venha em paz!"},{"a":"polonia","t":"Macacos me mordam! Um maldito cavaleiro..."},{"a":"polonia","t":"Hã, veja bem, eu sou uma pirata legal, tipo aquele tal de... Robin Hood."},{"a":"polonia","t":"...Eu tiro dos ricos e dou aos pobres!"},{"a":"argon","t":"Ah! Isso parece bem nobre. Muito bem, continue!"},{"a":"polonia","t":"...Ufa."},{"a":"tavern","t":"Também não teve sorte hoje?"},{"a":"polonia","t":"Arr, a vida em alto mar é dureza."}]},{"id":"polonia_02","i":2,"title":"A História de Del Monte","req":"polonia:2","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"tavern","t":"Não vai mais recrutar hoje, Polônia?"},{"a":"polonia","t":"É inútil. Sou um fracasso como capitã, e ainda mais como Del Monte..."},{"a":"tavern","t":"Esse Baross Del Monte... era avô seu?"},{"a":"polonia","t":"Isso! Uma lenda entre as lendas! Os tempos modernos são dureza pros piratas..."},{"a":"polonia","t":"Hoje em dia, tudo que é navio mercante tem ferramentas mágicas contra a gente, os cães do mar."},{"a":"polonia","t":"Mas não Baross! Com ou sem magia, ele surgia sempre da neblina!"},{"a":"polonia","t":"Roubava tudo que era item de valor deles, e deixava pra trás só sua gargalhada como cartão de visita..."},{"a":"polonia","t":"Mesmo depois de todos os piratas se aposentarem, ele continuou aterrorizando os mares por décadas!"},{"a":"tavern","t":"É um legado e tanto, o seu!"},{"a":"polonia","t":"Sim! E depois de cada viagem, ele sempre achava tempo pra visitar a neta e encher ela de histórias de aventura..."},{"a":"polonia","t":"Icem a bandeira negra! Disparem os canhões! Todos homens a estrobordo, é hora do saque!"},{"a":"tavern","t":"Estrobordo? Não devia ser estibordo?"},{"a":"polonia","t":"...Argh! Maldição! Eu não passo de uma marinheira de água doce com roupas bonitas se esforçando pra parecer uma pirata."},{"a":"polonia","t":"De que vale um pirata sem navio, hein?"},{"a":"tavern","t":"Não tem navio? Talvez fosse melhor começar com isso."},{"a":"polonia","t":"Hein?"},{"a":"tavern","t":"Um capitão sem navio não vai conseguir uma tripulação!"},{"a":"tavern","t":"Mas, se você precisa de um navio, acho que conheço a pessoa certa."},{"a":"polonia","t":"...Sério?"},{"a":"polonia","t":"Quer dizer, pelas barbas de Davy Jones, obrigada, taverneira! A Capitã Polônia tá te devendo!"},{"a":"tavern","t":"Ah, pode acreditar, estou contando com isso."}]},{"id":"polonia_03","i":3,"title":"Construtor de respeito","req":"polonia:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"carpenter","t":"Quer que eu faça um navio inteiro??"},{"a":"polonia","t":"Isso. Cê consegue?"},{"a":"carpenter","t":"Pode apostar! Será a minha obra-prima! Quero ver esses planos."},{"a":"carpenter","t":"Hmm... são bem elaborados. Que rabiscos são esses?"},{"a":"polonia","t":"A minha letra. Eu não sei ler."},{"a":"carpenter","t":"Ah, isso explica algumas coisas. Ainda assim, isso está mais que bom."},{"a":"polonia","t":"Yo ho ho! Será o maior navio que esses mares já viram desde Baross e Bonaventura!"},{"a":"carpenter","t":"Mas tem a questão do preço. Tem certeza que você pode bancar??"},{"a":"polonia","t":"Sim, dobrões não serão problema. Fabrique o navio, eu cuido do dinheiro."}]},{"id":"polonia_a","i":3,"title":"Mão amiga","req":"polonia:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fichas da fortuna"},"side":true,"lines":[{"a":"polonia","t":"Olá, bela senhorita. Cê é uma curandeira, né não?"},{"a":"priest","t":"Ah, sim! Eu sou Freyja, sacerdotisa deste tem-"},{"a":"polonia","t":"Corta a minha perna."},{"a":"priest","t":"Como é?"},{"a":"polonia","t":"Eu pedi pra cortar a minha perna!"},{"a":"priest","t":"Cruz credo, não! Por que alguém pediria uma coisa dessas?"},{"a":"polonia","t":"Eu sou pirata! Que tipo de capitã pirata não tem uma porcaria de perna de madeira?!"},{"a":"polonia","t":"É só cortar a minha perna e me consertar com a tua magia e pimba!"},{"a":"priest","t":"De jeito nenhum. Eu fiz um juramento para a Deusa de nunca ferir um ser humano."},{"a":"polonia","t":"Argh, sua rata de fossa! Tá bom! Mas cê não vai ganhar nada dos meus dobrões!"},{"a":"priest","t":"... Que garota estranha."}]},{"id":"polonia_04","i":4,"title":"O tesouro da capitã","req":"polonia:4","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"polonia","t":"Arr, esses yetis tão cheios da grana! Vou arrumar a grana pro navio rapidinho!"},{"a":"leather","t":"Beleza, cara, estou aqui. E agora?"},{"a":"polonia","t":"É Capitã Polônia pra ti, sua ratazana!"},{"a":"leather","t":"Claro, cara capitã. O que quer que eu faça?"},{"a":"polonia","t":"Cê trouxe a carroça. Carrega o tesouro enquanto eu roubo até as calças desses yetis."},{"a":"leather","t":"Uau, capitã. Você rouba dessas criaturas lindas e peludas?"},{"a":"polonia","t":"Sim. Por algum motivo, eles tão carregando um monte de itens valiosos, tipo martelos de guerra e arcos compostos."},{"a":"leather","t":"E as peles, capitã? Posso ficar com elas?"},{"a":"polonia","t":"Tome tento, sua ratazana! Piratas saqueiam, não matam!"},{"a":"leather","t":"Ah, que desperdício."},{"a":"polonia","t":"Nem um pouco. Se a gente deixar as vítimas com vida, elas podem conseguir mais tesouros pra roubar depois. Economia básica!"},{"a":"polonia","t":"E continue, se quiser a sua parte, sua ratazana!"},{"a":"leather","t":"Sim senhora, capitã."}]},{"id":"polonia_05","i":5,"title":"Viagem de estreia","req":"polonia:5","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"carpenter","t":"Aí está, minha obra-prima!"},{"a":"polonia","t":"É... é lindo. Cê trouxe água a estes olhos cheios de sal."},{"a":"carpenter","t":"Não é? Eu tive que cortar algumas coisas, tipo a sua estranha insistência por canhões no topo do cesto de gávea..."},{"a":"carpenter","t":"Mas acho que ficou muito bom, não concorda?"},{"a":"polonia","t":"Com certeza, marujo. Tá aqui o seu tesouro, merecido."},{"a":"carpenter","t":"Mereci mesmo! Só mais uma coisinha. Eu até posso ser um mestre carpinteiro, mas panos e tecidos estão além da minha conta."},{"a":"carpenter","t":"...E sem uma vela, o seu navio não vai zarpar tão cedo!"},{"a":"polonia","t":"Cê já deixou capitã bem orgulhosa, marujo. Eu tenho uma vela bem aqui."},{"a":"carpenter","t":"Uau! Isso sim é uma obra de arte! E de magia! Onde conseguiu isso!"},{"a":"polonia","t":"Uma herança do meu vovô Baross. A vela que já embalou o próprio navio dele: o lendário Bonaventura!"},{"a":"carpenter","t":"Entendi! Um belo toque final nesta embarcação!"},{"a":"carpenter","t":"Muito bem, Capitã Polônia, o Esplêndido Allan é todo seu!"},{"a":"polonia","t":"Cê chamou o barco de Esplêndido Allan? Peraí..."},{"a":"polonia","t":"Aquela figura de proa... é tu! E tá peladão ainda por cima!"},{"a":"carpenter","t":"Ha ha! Não imagino outra figura de proa para um navio tão perfeito!"}]},{"id":"polonia_b","i":5,"title":"Dá no pé!","req":"polonia:5","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fichas da fortuna"},"side":true,"lines":[{"a":"polonia","t":"Ei, e aí."},{"a":"wood","t":"Sim?"},{"a":"polonia","t":"Corta a minha perna."},{"a":"wood","t":"Claro."},{"a":"polonia","t":"Eu disse... epa, cê tá de boa com isso?"},{"a":"wood","t":"Claro. É só esticar a perna assim. Esse machado velho deve dar pro gasto."},{"a":"polonia","t":"Hã, peraí!"},{"a":"wood","t":"Não vai ser bonito, mas você é uma garota durona, certo?"},{"a":"wood","t":"Só não esquece de aplicar um torniquete. Você não vai querer morrer de hemorragia."},{"a":"polonia","t":"Basta, marujo! Calminha aí!"},{"a":"polonia","t":"Eu... o meu navio já vai zarpar! E-eu preciso ir! Até mais!"},{"a":"wood","t":"Ha! Humanos. Nunca fica chato."}]},{"id":"polonia_06","i":6,"title":"Legado no mar","req":"polonia:6","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"sia","t":"Meu rei, trago péssimas notícias."},{"a":"king","t":"Oh, não! A Cidade Perdida de Ouro está sem ouro!?"},{"a":"sia","t":"Nada tão terrível, felizmente."},{"a":"sia","t":"No entanto, uma pirata metida infelizmente anda saqueando sua frota mercante pessoal."},{"a":"sia","t":"...Estima-se que o roubo seja de mais de 100 trilhões em ouro."},{"a":"king","t":"Pela deusa! E o radar mágico antipirataria da minha frota?"},{"a":"sia","t":"Absolutamente inócuo, ao que parece. Tal como o grandioso Baross, este navio elude até nossos melhores feitiços..."},{"a":"sia","t":"...Saqueando seu ouro antes de sumir no mar."},{"a":"king","t":"Absolutamente bárbaro! E quanto à tripulação?"},{"a":"sia","t":"Poupada, meu rei. Desde que não oferecessem resistência."},{"a":"king","t":"Ouro é um pequeno preço a se pagar. Comerei como um plebeu até que minha fortuna seja restaurada!"},{"a":"king","t":"...Quanto tempo isso vai levar?"},{"a":"sia","t":"Aproximadamente dois dias, meu rei."},{"a":"king","t":"Tempos sombrios nos aguardam..."}]},{"id":"polonia_07","i":7,"title":"Desembarque","req":"polonia:7","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"polonia","t":"Yo ho ho! Capitã Polônia na costa! A bebida por minha conta!"},{"a":"tavern","t":"Polônia! Ou, devo dizer... Capitã Polônia! Seus \"negócios\" vão bem, suponho."},{"a":"polonia","t":"Pode apostar, seu marinheiro de água doce! O mar é uma donzela cheia de joias, e tá desprotegida!"},{"a":"polonia","t":"Onde meu barco vai, as velas do meu vozinho pegam o vento como eu nunca vi!"},{"a":"tavern","t":"Aposto que Baross estaria orgulhoso. Como pretende gastar seus... ganhos ilícitos?"},{"a":"polonia","t":"Como qualquer pirata que se preze. Vou esconder aqui e ali com a minha tripulação."},{"a":"tavern","t":"Oooh! Mapas do tesouro! Adoro!"},{"a":"polonia","t":"Isso aí, é assim que os piratas fazem. Guarda um pouco pros meses de inverno, igual a um esquilo."},{"a":"tavern","t":"E quanto ao resto?"},{"a":"polonia","t":"Dei pra moça do templo."},{"a":"tavern","t":"Uma doação para um orfanato? Não pensei que você fosse tão caridosa."},{"a":"polonia","t":"Orfa-quem?"},{"a":"tavern","t":"Não importa. Pois bem, o que posso lhe servir, capitã?"},{"a":"polonia","t":"Meu favorito: bebida de sal velho! E praqueles marinheiros de água doce que acham que aguentam o tranco..."},{"a":"polonia","t":"A próxima rodada é por minha conta! A família Baross tá de volta na parada! Yo ho ho!"}]},{"id":"polonia_08","i":8,"title":"Sussurros do Passado","req":"polonia:8","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"polonia","t":"Pronto para o próximo mergulho, sereio?"},{"a":"baker","t":"Sempre, capitã! Embora, devo admitir..."},{"a":"baker","t":"Embora eu sempre goste de ajudar em exploração submarina, eu não me inscrevi para ser pirata!"},{"a":"polonia","t":"Não esquenta. É uma missão de mapeamento. Sua capitã tá ampliando o território."},{"a":"polonia","t":"Nada de pirataria. Mas, se a gente tiver sorte, pode achar um navio afundado pra saquear! Yo ho ho!"},{"a":"baker","t":"Hã, capitã? Que navio é aquele no horizonte?"},{"a":"polonia","t":"Arr. Calma lá, sereio. É o Bonaventura! O navio do meu vô."},{"a":"baker","t":"Tem certeza? Ele parece bem gasto..."},{"a":"polonia","t":"Pelas barbas de Netuno! O-O maldito Bonaventura! Mas é impossível! Meu vô morreu faz anos!"},{"a":"polonia","t":"M-Marujos! Mudança de planos! VAMOS DAR NO PÉ!"}]},{"id":"polonia_09","i":9,"title":"Uma lenda à deriva","req":"polonia:9","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"baker","t":"Nunca pensei que fosse subir num navio dilapidado."},{"a":"polonia","t":"Cuidado onde pisa, sereio. Esse navio tá em mau estado."},{"a":"baker","t":"Sinceramente, preferia ir nadar! O que viemos fazer nesse barco, pra começo de conversa?"},{"a":"polonia","t":"Com assim o que a gente veio fazer? É o Bonaventura de Baross!"},{"a":"polonia","t":"Tenho que descobrir o que aconteceu aqui... Esse navio velho num devia estar no mar..."},{"a":"baker","t":"Está mais pra navio fantasma."},{"a":"polonia","t":"Argh, num me assusta assim! Fantasma num existe!"},{"a":"baker","t":"Mas e Zo..."},{"a":"polonia","t":"C-Chega, marujo. Eu tô procurando pistas."},{"a":"baker","t":"Esse diário ali parece meio sinistro..."},{"a":"polonia","t":"Arrr, o diário do capitão!"},{"a":"baker","t":"Parece estar olhando para você... né?"},{"a":"polonia","t":"'Cê vem comigo, diário. E olho vivo em busca de pistas."},{"a":"polonia","t":"Marujo... pode parar de pegar no meu cabelo?"},{"a":"baker","t":"Capitã, eu estou aqui."},{"a":"polonia","t":".....AAAAAARGH!!! Abandonar navio!"}]},{"id":"polonia_10","i":10,"title":"Herança Pirata","req":"polonia:10","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"polonia","t":"A capitã está de volta a bordo, tripulação. Içar velas, vamos partir!"},{"a":"baker","t":"Capitã, olha! O Bonaventura está afundando!"},{"a":"polonia","t":"Cracas! Como é possível? Depois desse tempo todo?! O diário tava mantendo ele de pé?"},{"a":"baker","t":"Talvez ele tenha cumprido o propósito."},{"a":"polonia","t":"Baross, seu cão sarnento... Como ia saber?"},{"a":"baker","t":"Polônia, e quanto ao diário?"},{"a":"polonia","t":"É mesmo, deixa eu ver..."},{"a":"polonia","t":"..............."},{"a":"polonia","t":"Eu tenho outro favor pra te pedir, sereio."},{"a":"baker","t":"Ah, é, deixa eu ler para você."},{"a":"baker","t":"Hã... Parecem instruções para encontrar um local submerso."},{"a":"polonia","t":"O Templo Afundado? Isso é história velha."},{"a":"baker","t":"Não, parece ser bem longe de lá... Algo sobre a Cidade Perdida de Ouro?"},{"a":"baker","t":"Mas a Cidade Perdida de Ouro não fica embaixo d'água..."},{"a":"polonia","t":"Q-Quer dizer que num é só uma lenda? Existe mesmo?"},{"a":"polonia","t":"Sereio, 'cê nada. É o destino."},{"a":"polonia","t":"Se as histórias forem reais... 'cê num vai se arrepender de me levar lá."}]},{"id":"polonia_11","i":11,"title":"A Cidade Afundada de Ouro","req":"polonia:11","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"baker","t":"Ufa! Chegamos! Como está se segurando, capitã?"},{"a":"polonia","t":"*Cof* *Argh*..."},{"a":"polonia","t":"Ufa... 'Cê tem... pernas fortes... pra um sereio..."},{"a":"baker","t":"E que bom, né! Essa entrada fica tão no fundo que humano nenhum chegaria aqui."},{"a":"polonia","t":"Tem razão! Eu quase me afoguei. Nunca mais volto pra cá..."},{"a":"baker","t":"Pela Deusa... Polônia, veja só!"},{"a":"polonia","t":"Barbas de cracas... A Cidade Afundada de Ouro..."},{"a":"polonia","t":"Esse lugar... Nunca vi nada assim..."},{"a":"baker","t":"É riqueza até dizer chega! Pérolas de ouro... A Cidade Perdida de Ouro parece um chiqueiro em comparação!"},{"a":"polonia","t":"Por toda a vida, meu vô procurou esse lugar..."},{"a":"baker","t":"No fim, ele não conseguiu levar nada de volta à terra, então deixou tudo para a neta favorita."},{"a":"polonia","t":"Sniff... Tô ficando com o olho marejado..."},{"a":"baker","t":"Quer um momento, capitã?"},{"a":"polonia","t":"Tá brincando? Tem saque pra gente pegar! E 'cê acabou de ser promovido pra Imediato. Tá pronto pra nadar?"},{"a":"baker","t":"Eu vou carregar sacos de espólios e TAMBÉM ser pirata? É melhor eu me alongar!"}]},{"id":"polonia_epilogue","i":12,"title":"Epílogo","req":"polonia:11","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"polonia","t":"Hmm..."},{"a":"baker","t":"Vamos nos preparar para outro nado, Polônia?"},{"a":"polonia","t":"Nem, marujo. Eu tô com um problema."},{"a":"polonia","t":"Tô com dinheiro demais! Quase ficando sem praia onde enterrar."},{"a":"baker","t":"Admito que estou com demais na minha parte, também."},{"a":"baker","t":"Ah, o que me lembra!"},{"a":"baker","t":"Fui nadar perto do Bonaventura afundado mais cedo..."},{"a":"baker","t":"Não havia muito digno de nota, mas achei esse tapa-olho. Reconhece?"},{"a":"polonia","t":"Imediato! É o tapa-olho do Baross!"},{"a":"polonia","t":"Yo ho ho! Tô tão feliz que podia te tascar um beijo!"},{"a":"baker","t":"O prazer é meu, capitã. Sei que ele gostaria que você o encontrasse."},{"a":"polonia","t":"Quer saber... Pra mim, já chega desse lance de saquear embaixo d'água."},{"a":"polonia","t":"O mar que é casa de pirata, não uma cidade de ouro qualquer! Por mais saque que tenha lá."},{"a":"polonia","t":"Como a neta do grande Baross, eu te dou a Cidade Afundada de Ouro com todo o saque que tem lá dentro ainda."},{"a":"polonia","t":"Brigada pelo serviço, Imediato. Se mudar de ideia sobre ser pirata, pode vir com a gente."},{"a":"baker","t":"Obrigado, capitã. Nunca vou me esquecer das nossas aventuras juntos!"},{"a":"baker","t":"Acho melhor eu voltar a falar com Tutu Mano sobre tirar férias!"}]}]},{"id":"king","name":"Reinhold","chapters":[{"id":"king_farewell","i":0,"title":null,"req":null,"reward":null,"side":false,"lines":[{"a":"sia","t":"Rei Reinhold..."},{"a":"king","t":"Ah... Ao que parece, minhas obrigações me alcançaram!"},{"a":"sia","t":"Alcançaram e \"acumularam\", eu diria. Os dignitários já estão aguardando."},{"a":"king","t":"Adeus, comerciante! Eu voltarei!"},{"a":"sia","t":"Hum, receio que não."}]},{"id":"king_01","i":1,"title":"A Corte do Rei","req":"king:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fichas da fortuna"},"side":false,"lines":[{"a":"king","t":"A Corte do Rei já está aberta! Peticionários, em frente!"},{"a":"rudo","t":"Hunf."},{"a":"king","t":"O que o reino de Reinhold pode fazer por seus súditos, ó grande... homem-urso?"},{"a":"rudo","t":"Acho que deveria banir a magia e expulsar todos os conjuradores."},{"a":"king","t":"Ah... isso é... hum..."},{"a":"king","t":"Levaremos... sua proposta em consideração! Próximo!"},{"a":"herbs","t":"Oiii! Acho que todos os dias deveriam ser DIA DA PIÑATA!"},{"a":"king","t":"Que ideia esplêndida! De fato, poderíamos..."},{"a":"sia","t":"..."},{"a":"king","t":"... passar muito tempo discutindo a questão! Obrigado pela presença!"},{"a":"king","t":"... Sia, quantos peticionários ainda temos para hoje?"},{"a":"sia","t":"Cinquenta e cinco, meu Rei."},{"a":"king","t":"Ai, minha nossa."}]},{"id":"king_02","i":2,"title":"Coração de Ouro do Tolo","req":"king:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fichas da fortuna"},"side":false,"lines":[{"a":"donovan","t":"Perdão, este assento já foi tomado?"},{"a":"sia","t":"Veio arruinar o meu dia de folga, Donovan?"},{"a":"donovan","t":"Assim você me ofende, Sia. Como cidadão imperial, estou meramente contatando uma companheira."},{"a":"donovan","t":"Como nosso Rei tolo tem passado ultimamente?"},{"a":"sia","t":"Sua espionagem já foi melhor, Donovan. Não poderia estar mais equivocado ao chamar Reinhold de tolo."},{"a":"sia","t":"Por trás dos sorrisos, ele está sempre se sacrificando pelo seu povo."},{"a":"sia","t":"Uma lição que o Imperador... NOSSO Imperador, poderia aprender."},{"a":"sia","t":"Minha função até o momento tem sido a de impedir que ele arruíne a si próprio em nome do seu povo."},{"a":"donovan","t":"É mesmo? Fascinante."},{"a":"sia","t":"Ele é, de fato, um tolo com um coração de ouro. Mas, se quiser subestimá-lo, faça isso por sua conta e risco."}]},{"id":"king_03","i":3,"title":"Hora Extra Real","req":"king:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fichas da fortuna"},"side":false,"lines":[{"a":"king","t":"Ufa! Essa pilha de relatórios não vai diminuir tão cedo, não é?"},{"a":"sia","t":"Talvez devêssemos nos preparar para mais uma noite em claro."},{"a":"king","t":"Obrigado pela sua assistência com isso, minha cara Sia!"},{"a":"sia","t":"Disponha, meu Rei. E, agora, vamos ao próximo relatório..."},{"a":"sia","t":"Os fazendeiros de Southburg não conseguiram pagar todos os impostos, alegando uma má colheita."},{"a":"sia","t":"Creio que já seja a segunda vez..."},{"a":"king","t":"Envie alguns feiticeiros da corte para investigar. Talvez haja algum tipo de praga assolando suas terras."},{"a":"sia","t":"Uma solução deveras generosa."},{"a":"king","t":"E conceda perdão aos impostos novamente. É o que meu pai faria!"},{"a":"sia","t":"Muito bem. De fato, creio que o Rei Keinan teria agido da mesma forma."},{"a":"king","t":"Realmente, a coroa deixada por ele possui um peso enorme..."},{"a":"king","t":"O que diz o próximo relatório?"},{"a":"sia","t":"Ele nos informa sobre tensões na fronteira com o Império vizinho.."}]},{"id":"king_04","i":4,"title":"Saltando nas Sombras","req":"king:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fichas da fortuna"},"side":false,"lines":[{"a":"king","t":"..."},{"a":"sia","t":"Meu Rei..."},{"a":"king","t":"Ahh!"},{"a":"king","t":"P-Por favor anuncie sua presença antes de se aproximar por trás!"},{"a":"sia","t":"Ah, aquele ataque-ninja ainda pesa bastante em sua mente, não?"},{"a":"king","t":"Claro! Eu sobrevivi por um triz!"},{"a":"sia","t":"Devo dobrar a guarda?"},{"a":"king","t":"Isso... não será necessário. Mas tente não ser tão furtiva de agora em diante, por favor!"},{"a":"sia","t":"Como quiser, meu Rei."},{"a":"hemma","t":"Ah, é tão bom estar em casa... Hum?"},{"a":"king","t":"ARGH!!! N-Ninjas?!"},{"a":"hemma","t":"Pedimos desculpas. Parece que cometemos um erro."},{"a":"hemma","t":"A Translocação Sombria pode ser um tanto quanto imprecisa, às vezes."},{"a":"king","t":"P-Por favor abstenham-se de realizar TRANSLOCAÇÕES SOMBRIAS na minha sala do trono!"},{"a":"sia","t":"R-Rei Reinhold? Está bem?"},{"a":"king","t":"Sim! Por favor, acompanhe essa... visita horripilante até a saída."},{"a":"sia","t":"Muito bem. Me certificarei de que o castelo esteja adequadamente protegido contra esse tipo de intrusão no futuro."},{"a":"hemma","t":"Mas que belo Ponto de Passagem encontramos. Nós retornaremos."},{"a":"king","t":"Espero mesmo que não!"}]}]},{"id":"rudo","name":"Rudo","chapters":[{"id":"rudo_01","i":1,"title":"A montanha vivente","req":"rudo:1","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"argon","t":"Brrr... Eu não estou com roupas apropriadas para esse frio! Por que estamos aqui mesmo?"},{"a":"lilu","t":"As joias daqui têm algumas propriedades maravilhosas! Grimar me contou que..."},{"a":"argon","t":"Espere, Lilu! Veja! Há um homem lutando contra um Yeti ali!"},{"a":"lilu","t":"Um homem!? Ele é tão grande quanto uma montanha!"},{"a":"lilu","t":"E ele está... nocauteando o Yeti!"},{"a":"rudo","t":"Ufa... Já foram dez."},{"a":"argon","t":"Uma impressionante luta, senhor! Você foi incrível!"},{"a":"rudo","t":"Hein?"},{"a":"lilu","t":"Senhor... você está ferido! Deixe-me curar você!"},{"a":"lilu","t":"<c1>Curan</c1>...!"},{"a":"rudo","t":"AFASTE-SE!"},{"a":"rudo","t":"Eu estou bem. O ferimento vai se curar sozinho."},{"a":"rudo","t":"Crianças como vocês não deveriam estar em um lugar como este. Vão para casa."},{"a":"argon","t":"Uau, aquele cara realmente odeia magia, hein?"},{"a":"lilu","t":"Não. O que eu vi nos olhos dele... era medo."}]},{"id":"rudo_02","i":2,"title":"Aviso de despejo","req":"rudo:2","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"elderowen","t":"Eu não estou entendendo..."},{"a":"rudo","t":"Bah! Então eu vou facilitar pros seus ouvidos de velha surda!"},{"a":"rudo","t":"O mago dessa cidade é um lunático desvairado que precisa ser expulso, pela segurança de todos."},{"a":"elderowen","t":"Ora, ora... que palavras duras..."},{"a":"rudo","t":"Ontem mesmo ele me mandou ficar de olho em Timotheus..."},{"a":"rudo","t":"...Afirmando que \"Tim\" estava delirando, confuso, e precisava ser mantido sob supervisão."},{"a":"rudo","t":"Ele *É* Timotheus!"},{"a":"elderowen","t":"Hmm, sim. Entendo."},{"a":"elderowen","t":"Apesar dessa... \"condição\", Timotheus Grimar é parte integrante dessa cidade."},{"a":"elderowen","t":"Ele é útil e inofensivo. Não vejo motivo para alarde."},{"a":"lilu","t":"Que história é essa de expulsar o mestre Grimar!?"},{"a":"rudo","t":"Não se meta, garota."},{"a":"lilu","t":"Não! Mestre Grimar é um mago poderoso, mas ele não machucaria uma mosca!"},{"a":"rudo","t":"Gah! Tá bom! Mas se essa cidade explodir, não digam que eu não avisei."},{"a":"elderowen","t":"Esse cara dá trabalho."},{"a":"lilu","t":"Melhor ficar de olho nele."}]},{"id":"rudo_03","i":3,"title":"Centelhantes","req":"rudo:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"priest","t":"Com licença... o que você está resmungando aí?"},{"a":"rudo","t":"Droga. Por que tem tantos feiticeiros nessa cidade..."},{"a":"priest","t":"Ah, sr. Rudo, eu presumo."},{"a":"rudo","t":"Não venha com esse papinho pra cima de mim, maga."},{"a":"priest","t":"Eu sou uma sacerdotisa da deusa, meus poderes são diferentes dos de um mago."},{"a":"priest","t":"Como parte o meu juramento, eu prometi dedicar a vida a curar e proteger."},{"a":"rudo","t":"Eu não acredito. Vocês centelhantes são todos iguais."},{"a":"priest","t":"Você sabe sobre a Centelha?"},{"a":"rudo","t":"Hunf. Esquece o que eu disse. Vou dar o fora daqui."},{"a":"priest","t":"...Você estava ouvindo, Lilu?"},{"a":"lilu","t":"Sim, ouvi tudo!"},{"a":"priest","t":"Você se lembra das lições sobre a Centelha?"},{"a":"lilu","t":"Claro! Apenas pessoas que nasceram com a Centelha podem controlar e manipular feitiços."},{"a":"lilu","t":"Mas o público geral não costuma conhecer esse fenômeno."},{"a":"priest","t":"Isso mesmo! Como eu esperava da minha melhor aluna!"},{"a":"priest","t":"Mas fica a pergunta... Como ele sabe a respeito?"},{"a":"lilu","t":"Hmm... Você acha que..."}]},{"id":"rudo_04","i":4,"title":"Bater e pegar","req":"rudo:4","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"polonia","t":"Yo ho ho! A Capitã Polônia acertou em cheio dessa vez!"},{"a":"polonia","t":"Uma tumba real inteirinha, pronta pra ser saqueada!"},{"a":"rudo","t":"Silêncio, marinheira. Não tenho tempo."},{"a":"polonia","t":"Ou estaria... Se não fosse um bárbaro beócio TRANSFORMANDO TODO O ESPÓLIO EM POEIRA!"},{"a":"polonia","t":"Em nome de Davy Jones, qual é o seu problema, marujo? Isso vale toneladas de dobrões!"},{"a":"rudo","t":"É antigo."},{"a":"rudo","t":"É mágico."},{"a":"rudo","t":"E provavelmente amaldiçoado."},{"a":"rudo","t":"Estou transformando tudo em pó para poupar outros do trabalho."},{"a":"rudo","t":"Se essa cidade é idiota a ponto de não ver o problema, então eu dou um jeito!"},{"a":"polonia","t":"Ei, marujo. Esse cajado tem cara de ser caro, não inventa de..."},{"a":"rudo","t":"Hunf."},{"a":"rudo","t":"...Ai."},{"a":"polonia","t":"Pelo Kraken! Não quebra nos teus joelhos!"},{"a":"polonia","t":"...Pela cara, quem quebrou alguma coisa foi o cajado. Nem um arranhão nele!"},{"a":"polonia","t":"E a tua perna, marujo?"},{"a":"rudo","t":"Está bem. Mas esse cajado é mais duro do que parece."},{"a":"rudo","t":"E, por algum motivo, não consigo soltar. Está tipo... colado na minha mão."},{"a":"polonia","t":"Eu não sou cirurgiã, mas tá com cara de ser uma maldição, marujo."},{"a":"polonia","t":"...Cê devia dar uma olhada nisso."},{"a":"rudo","t":"É claro que é uma maldição. É SEMPRE uma maldição."},{"a":"rudo","t":"Tá bom. Eu vou dar o fora. Quebrem o resto por mim."},{"a":"polonia","t":"Pode deixar!"},{"a":"polonia","t":"...Mais pra quebrar e invadir, porque esses piratas tão só pelo espólio."}]},{"id":"rudo_a","i":4,"title":"Amores brutos","req":"rudo:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fichas da fortuna"},"side":true,"lines":[{"a":"herbs","t":"Gorza!"},{"a":"gems","t":"Gorza!<sprite tint=1 name=Note2>"},{"a":"wood","t":"Ei, Juniper. E Maylee! Tudo bem?"},{"a":"herbs","t":"A gente estava falando sobre o futuro príncipe encantado dela..."},{"a":"gems","t":"Aaaah, mal posso esperar!"},{"a":"herbs","t":"...E estávamos pensando... Como você conheceu o seu?"},{"a":"wood","t":"Aquele trapalhão desajeitado do Rudo? Ha!"},{"a":"wood","t":"Pode não parecer, mas aquele homem sabe mesmo como falar com uma dama."},{"a":"wood","t":"Vejamos... Foi mais ou menos assim..."},{"a":"rudo","t":"...Mais um. Pra viagem."},{"a":"tavern","t":"Então... Rudo. Você já pensou em fixar raízes?"},{"a":"rudo","t":"Cuide da sua vida, Naya. Não tenho tempo pra isso."},{"a":"tavern","t":"O cupido ataca quando menos se espera! Quem sabe, a mulher dos seus sonhos pode aparecer a qualquer momento..."},{"a":"rudo","t":"Bah! Eu não vou fixar raízes por uma mulher que não consiga me derrubar."},{"a":"wood","t":"Isso é um desafio, grandalhão?"},{"a":"rudo","t":"Experimenta, dentuça!"},{"a":"tavern","t":"Gorza, largue a cadeira, por favor..."},{"a":"wood","t":"O que acha disso, seu pateta? Quer mais?"},{"a":"rudo","t":"RAAAAGH!!!"},{"a":"wood","t":"Uau!"},{"a":"wood","t":"...E casamos uma semana depois. O casamento mais sanguinolento que eu já vi."},{"a":"herbs","t":"..."},{"a":"gems","t":"..."},{"a":"herbs","t":"...T-talvez eu devesse falar com outra pessoa."}]},{"id":"rudo_05","i":5,"title":"Maldições e Explosões","req":"rudo:5","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"rudo","t":"Como assim você não pode quebrar!?"},{"a":"master","t":"É isso mesmo que você ouviu, meu amigo violento. Eu não consigo quebrar essa relíquia."},{"a":"rudo","t":"Para que serve um martelo de adamantina se ele não consegue quebrar esse cajadinho de nada!?"},{"a":"master","t":"Olha, com certeza de nada ele não é... Parece bem maligno para mim!"},{"a":"master","t":"De qualquer forma, tem mais alguma coisa nele, provavelmente algo mágico..."},{"a":"rudo","t":"É CLARO que é mágico."},{"a":"rudo","t":"É sempre uma maldição."},{"a":"master","t":"Parece que você já sabia disso! Por que veio atrás de mim e não de alguém entendido nessas coisas?"},{"a":"rudo","t":"Não se pode confiar em magos... Nem um pouco."},{"a":"master","t":"Olha, acho que você não tem muita escolha agora, criança."},{"a":"master","t":"Além do mais, como você não confiou na Lilu logo de cara? Ela é encantadora!"},{"a":"rudo","t":"Ela é uma maga, não é? Então ela é que nem os outros."},{"a":"rudo","t":"Perigosa Traiçoeira. VIL."},{"a":"master","t":"Bom, provavelmente ela é a única que pode ajudar, se você quiser se livrar desse cajado."},{"a":"rudo","t":"...Droga."}]},{"id":"rudo_06","i":6,"title":"Feiticeiro Involuntário","req":"rudo:6","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"rudo","t":"Oi, Naya, o de sempre."},{"a":"tavern","t":"Desculpa, Rudo, sem armas aqui dentro. Você conhece as regras."},{"a":"rudo","t":"Isso? É só uma bengala."},{"a":"tavern","t":"Acho que não! Eu reconheço um cajado mágico quando vejo um!"},{"a":"rudo","t":"Agh. Tá bom. Tá vendo isso? Totalmente amaldiçoado. Não consigo tirar."},{"a":"tavern","t":"Minha nossa! Acho que podemos fazer uma pequena exceção, nesse caso. Só para você!"},{"a":"rudo","t":"Hunf. Obrigado."},{"a":"tavern","t":"Então, o que você vai fazer a respeito disso?"},{"a":"rudo","t":"Não se preocupe com isso. Vou aprender a conviver."},{"a":"tavern","t":"Sério? Eu diria que está te deixando mal-humorado. Mais do que o normal, se é que isso é possível."},{"a":"tavern","t":"Além do mais, olhando pra você, qualquer um imaginaria que você é algum tipo de mago."},{"a":"rudo","t":"...Sério? Um maldito mago?"},{"a":"tavern","t":"Você só precisa de um chapéu bobo! E melhorar o humor!"},{"a":"rudo","t":"...Você pode ter razão. Tenho que fazer algo sobre isso. Até mais."},{"a":"tavern","t":"Tenha um bom dia. Vou colocar isso na sua conta!"}]},{"id":"rudo_07","i":7,"title":"Vislumbre do Trauma","req":"rudo:7","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"rudo","t":"Me desculpa por antes. Me disseram que você poderia... me ajudar com essa maldição."},{"a":"lilu","t":"O cajado, hein? Parece terrível!"},{"a":"lilu","t":"Nunca tentei neutralizar uma maldição antes, mas na teoria... acho que consigo."},{"a":"lilu","t":"Tem certeza que tá pronto pra isso? Você tá muito tenso."},{"a":"rudo","t":"...Sim."},{"a":"lilu","t":"Certo! Deixa eu me concentrar..."},{"a":"lilu","t":"Estou vendo a maldição... toda enrolada em você."},{"a":"lilu","t":"Espera aí, preciso ir mais fundo..."},{"a":"rudo","t":"...Hngh!"},{"a":"lilu","t":"Uau!"},{"a":"lilu","t":"Parecia que você ia me dar um soco DE VERDADE agora!"},{"a":"rudo","t":"...Desculpa. Não era a intenção."},{"a":"lilu","t":"Acho que isso não vai funcionar. Preciso me concentrar, sabe?"},{"a":"rudo","t":"É, a culpa é minha. Vou dar outro jeito."},{"a":"lilu","t":"Que tal falar com a Malady? Talvez ela possa ver algo que eu não consegui."},{"a":"rudo","t":"A Malady, hã? Vou tentar."},{"a":"lilu","t":"Mas seja gentil! Ela tem... circunstâncias especiais que você deve saber..."}]},{"id":"rudo_08","i":8,"title":"Uma Maldição para Dois","req":"rudo:8","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"rudo","t":"Srta. Malady, tem um minutinho?"},{"a":"malady","t":"(Ah, não, Lilu me falou dele...)"},{"a":"malady","t":"Hum... perdão. Acho que não..."},{"a":"rudo","t":"Foi mal, não quis te assustar. Achei que você soubesse alguma coisa sobre esse cajado."},{"a":"malady","t":"Eu... achei que você detestava magia?"},{"a":"rudo","t":"Mais do que qualquer coisa no mundo."},{"a":"rudo","t":"Mas você foi amaldiçoada, não foi? Eu também."},{"a":"rudo","t":"Você não escolheu a magia. Não é culpa sua."},{"a":"malady","t":"... Nesse caso, eu posso tentar... falar com o cajado."},{"a":"malady","t":"..."},{"a":"malady","t":"... Parece ser um parasita. Ele se alimenta da sua Faísca."},{"a":"rudo","t":"Essa coisa é inteligente?"},{"a":"malady","t":"Sim... de certo modo."},{"a":"malady","t":"Sua Faísca parece ser muito forte. Pode levar décadas, mas..."},{"a":"malady","t":"... Talvez ele possa te libertar da sua magia?"},{"a":"rudo","t":"Hunf. Eu não contaria com isso."},{"a":"rudo","t":"Então ele só quer alguém pra ficar sugando magia, né?"},{"a":"malady","t":"Hm... sim. Mais ou menos."},{"a":"malady","t":"Por favor... Eu já fui amaldiçoada, então..."},{"a":"rudo","t":"Hah! Eu nem pensaria nisso, moça."},{"a":"rudo","t":"Valeu pela ajuda. Acho que tive uma ideia..."}]},{"id":"rudo_09","i":9,"title":"O Passado de um Soldado","req":"rudo:9","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"malady","t":"Hm... posso entrar?"},{"a":"veteran","t":"Oh, a Medusa de quem tanto ouço falar."},{"a":"veteran","t":"Pode entrar, novata. Mas não temos cadeiras do seu tamanho, infelizmente."},{"a":"malady","t":"Está tudo bem... obrigada. Eu queria perguntar sobre aquele homem, o Rudo."},{"a":"veteran","t":"Aquele bobão? Ele não incomodou você, né?"},{"a":"malady","t":"Não, ele foi... estranhamente gentil comigo."},{"a":"veteran","t":"Sério? Que estranho, ele detesta magia."},{"a":"malady","t":"Foi por isso que eu vim. Eu queria perguntar... por quê?"},{"a":"veteran","t":"Fizemos parte do exército do Império algum tempo atrás. Velhos colegas de guerra."},{"a":"veteran","t":"O Rudo... se \"voluntariou\" a fazer parte de um experimento, que busca implantar Faísca artificialmente nos soldados."},{"a":"veteran","t":"Aquilo foi terrível. Ele nunca mais foi o mesmo."},{"a":"malady","t":"Que horrível... "},{"a":"veteran","t":"Foi muito pior do que parece. Saímos de lá o mais rápido que podíamos."},{"a":"malady","t":"Pelo menos... deu certo? Senti uma Faísca extremamente poderosa nele..."},{"a":"veteran","t":"É difícil dizer. Você viu como ele é. Nem mesmo o próprio imperador conseguiu fazê-lo conjurar o feitiço mais simples."},{"a":"malady","t":"E agora... graças a isso, ele está sofrendo com uma terrível maldição... Como podemos ajudar?"},{"a":"veteran","t":"Ele veio falar com você, não veio? Ele ter pedido ajuda é um bom sinal! "},{"a":"veteran","t":"Ele não é o mais esperto, mas o rapaz é teimoso. Tenho certeza de que ele vai pensar em alguma coisa."}]},{"id":"rudo_10","i":10,"title":"Transferência de Propriedade","req":"rudo:10","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"rudo","t":"Tá legal, seu palitinho nojento. Vamos fazer um acordo."},{"a":"rudo","t":"Vou entregar você para aquela troubelin ali."},{"a":"monster_Forest_Blacksmith","t":"A-argh! Me... solta!"},{"a":"rudo","t":"Você faz amizade com ele e nós esquecemos de tudo isso que aconteceu."},{"a":"rudo","t":"Se não quiser fazer isso..."},{"a":"rudo","t":"Eu mergulho nessa lava e nós vemos quem aguenta mais."},{"a":"rudo","t":"Então, o que vai ser? A \"água\" deve estar uma delícia, se quiser saber!"},{"a":"monster_Forest_Blacksmith","t":"..."},{"a":"rudo","t":"Boa escolha. Divirta-se com isso, troubelin."},{"a":"monster_Forest_Blacksmith","t":"Urgh! Tá... preso!"},{"a":"rudo","t":"Hua ha ha! Até mais!"}]},{"id":"rudo_epilogue","i":11,"title":"Epílogo","req":"rudo:11","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"lilu","t":"Rudo! Sobre o que aconteceu..."},{"a":"rudo","t":"Hm?"},{"a":"lilu","t":"Ah! Você se livrou do cajado!"},{"a":"rudo","t":"Isso mesmo. Uma coisa a menos para se preocupar."},{"a":"rudo","t":"...Me desculpe pelo que aconteceu. Eu estava meio tenso."},{"a":"lilu","t":"...Acho que posso te perdoar. Mas você precisa melhorar a forma como trata os magos!"},{"a":"rudo","t":"Hah! A Malady foi uma ajuda inesperada. Quem sabe, talvez eu mude algum dia."},{"a":"lilu","t":"Ela conseguiu tirar a maldição?"},{"a":"rudo","t":"Não exatamente. Mas, graças a ela, encontrei uma ajuda... inesperada."},{"a":"rudo","t":"Um pouco de cooperação de vez em quando não faz mal a ninguém. Hua ha!"},{"a":"argon","t":"Ashley, cuidado! Tem outra coisa vindo!"},{"a":"ashley","t":"Eu estou pronta pra qualquer coisa! Pode vir, fera!"},{"a":"monster_Forest_Blacksmith","t":"...Socorro..."},{"a":"argon","t":"Hein?"},{"a":"ashley","t":"Heeeeeein?"}]}]},{"id":"sia","name":"Sia","chapters":[{"id":"sia_01","i":1,"title":"Primeiros passos reais","req":"sia:1","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"king","t":"Sia! Eu decidi!"},{"a":"sia","t":"Sim, meu rei?"},{"a":"king","t":"Hoje eu gostaria de fazer compras!"},{"a":"sia","t":"Uma excelente ideia, Vossa Majestade."},{"a":"sia","t":"No entanto, de acordo com a sua agenda, você tem uma reunião com dignitários estrangeiros hoje..."},{"a":"king","t":"Ah, que chato! Não podemos mandá-los embora?"},{"a":"sia","t":"Lembre-se, meu rei, embora você seja jovem, ainda é rei. Sua palavra é lei."},{"a":"king","t":"...Você está absolutamente certa! Vamos às compras, então! Esses dignitários podem esperar!"},{"a":"sia","t":"Sua determinação é admirável. Devo acompanhá-lo?"},{"a":"king","t":"Claro! Não confio em mais ninguém para me proteger."}]},{"id":"sia_02","i":2,"title":"Amigos em lugares baixos","req":"sia:2","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"sia","t":"...Tenho razões para acreditar que a vida do nosso rei pode estar em perigo."},{"a":"elderowen","t":"De fato, alguns reinos rivais se beneficiariam de um atentado contra a vida do rei."},{"a":"elderowen","t":"Eu não vi ninguém suspeito, mas tenho certeza que Naya, na taverna, teria mais informações."},{"a":"sia","t":"Obrigada, ancião, por sua sabedoria e patriotismo."},{"a":"elderowen","t":"O prazer é meu. É meu dever como residente garantir a prosperidade do nosso reino."},{"a":"elderowen","t":"Embora ele possa ser jovem e tolo, tenho certeza de que Reinhold se tornará um excelente rei no futuro."},{"a":"sia","t":"E é meu dever mantê-lo vivo até lá!"},{"a":"tavern","t":"Ora, ora, não é sempre que vemos sangue azul aqui embaixo na taverna!"},{"a":"sia","t":"Deixa disso, Naya, você sabe quem eu sou."},{"a":"tavern","t":"Sei sim! Sia Leonel, um presente para o nosso rei do imperador de Kern..."},{"a":"tavern","t":"Para atuar como conselheira, mas também para ficar de olho nele, estou certa?"},{"a":"sia","t":"...!"},{"a":"sia","t":"...Você é intrometida, hein?"},{"a":"sia","t":"Bem, então me diga, Naya intrometida..."},{"a":"sia","t":"Você tem visto algum rosto estranho em sua taverna ultimamente?"},{"a":"tavern","t":"Ah, muitos rostos estranhos passam por aqui! Orcs bêbados, comerciantes..."},{"a":"tavern","t":"Mas o mais estranho de todos seria o daquela garota ali no canto."},{"a":"yami","t":"...!"},{"a":"sia","t":"Ela escapou..."},{"a":"sia","t":"Aquela era uma espiã azuman... ou assassina!"},{"a":"sia","t":"Eu precisarei ser mais vigilante..."}]},{"id":"sia_03","i":3,"title":"Quebra-portões","req":"sia:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"sia","t":"Nós reunimos vocês aqui hoje para celebrar a incrível generosidade do Rei."},{"a":"sia","t":"Nos últimos meses, ele doou vários milhões de ouro de seus próprios cofres..."},{"a":"sia","t":"...Para vários templos, escolas e orfanatos locais."},{"a":"sia","t":"Todos são bem-vindos a este banquete, então contem para seus amigos e familiares."},{"a":"sia","t":"Vida longa ao Rei Reinhold!"},{"a":"yami","t":"Tirano Reinhold, seu reinado termina agora!"},{"a":"king","t":"Aaargh..."},{"a":"sia","t":"Uma shuriken...! A espiã azuman!"},{"a":"sia","t":"Guardas! Formem um perímetro ao redor do castelo! Não deixem ninguém escapar!"},{"a":"sia","t":"Argon, vá atrás daquela assassina!"},{"a":"argon","t":"Rápido!"},{"a":"sia","t":"Você! Bufão fedorento! O rei está ferido! Procure um curandeiro imediatamente!"},{"a":"leather","t":"Ei, que rude."},{"a":"sia","t":"(Eu tinha cada ponto de entrada sob vigilância máxima...)"},{"a":"sia","t":"(...Quem é essa garota?)"}]},{"id":"sia_04","i":4,"title":"Cartas chamuscadas","req":"sia:4","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"sia","t":"Naya intrometida, acho que você me deve algumas explicações."},{"a":"tavern","t":"Ah, Sra. Leonel... acho que VOCÊ me deve algumas explicações."},{"a":"sia","t":"O que você quer dizer?"},{"a":"tavern","t":"Eu interceptei algumas cartas MUITO interessantes. Enviadas por você, acredito."},{"a":"tavern","t":"Que tal as lermos juntas?"},{"a":"sia","t":"...!"},{"a":"tavern","t":"Vejamos... Um selo de Kern, endereçada diretamente ao imperador de Kern?"},{"a":"tavern","t":"Caramba. Eu estava ansiosa por um caso de amor escandaloso, mas acho que traição serve também."},{"a":"sia","t":"N-naya, pare, por favor!"},{"a":"tavern","t":"Ah! Aqui está uma parte interessante!"},{"a":"tavern","t":"“Rei Reinhold é um completo idiota cuja presença no trono lhe beneficia bastante.\""},{"a":"tavern","t":"\"Mantê-lo vivo com certeza prejudicará seu reino, muito mais do que a morte de seu governante.\""},{"a":"sia","t":"..."},{"a":"tavern","t":"Tais palavras indelicadas são bem impróprias para a conselheira do rei!"},{"a":"sia","t":"Naya... intrometida... Você vai pagar por isso!"},{"a":"tavern","t":"Algum dia, talvez. Mas por enquanto, acredito que é você quem vai pagar. Muito caro, suponho."},{"a":"sia","t":"...Você está me chantageando?"},{"a":"tavern","t":"Um pecado tão pequeno, comparado à traição!"},{"a":"tavern","t":"Por outro lado, se você tivesse planejado fazer mal ao nosso rei..."},{"a":"sia","t":"Aff. Tudo bem. Diga seu preço. E reze para que minha rede de espionagem nunca supere a sua, Naya."},{"a":"tavern","t":"Estou ansiosa para isso!"}]},{"id":"sia_a","i":4,"title":"O capricho do rei","req":"sia:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Fichas da fortuna"},"side":true,"lines":[{"a":"sia","t":"Meu Rei."},{"a":"king","t":"Querida Sia! Como posso ajudar?"},{"a":"sia","t":"Por acaso você teve algum de seus outros surtos de \"capricho\" recentemente?"},{"a":"king","t":"Nã-não! Claro que não! Jamais!"},{"a":"sia","t":"Estranho, nossas contas indicam que o Cofre 36 está quase transbordando com <c1>Kunai</c1>."},{"a":"sia","t":"Eu não preciso lembrar vossa majestade de que esse é um item extremamente raro."},{"a":"king","t":"Te-tenho certeza de há uma explicação per..."},{"a":"sia","t":"Além do mais, diversas das mais raras antiguidades do reino foram vistas nas mãos da plebe."},{"a":"sia","t":"Sua generosidade é louvável..."},{"a":"sia","t":"... Mas, por favor, evite distribuir artefatos inestimáveis para resolver suas crises de humor."},{"a":"king","t":"Hunf. Muito bem! A partir de hoje serei um novo homem!"},{"a":"sia","t":"Obrigada por compreender. Agora devo me retirar."},{"a":"king","t":"Minha vontade ainda é forte! Não necessito de bens materiais!"},{"a":"king","t":"...Este cômodo podia ter algumas <c1>Lâminas Reais</c1>, não é mesmo?"}]},{"id":"sia_05","i":5,"title":"Agente Swan","req":"sia:5","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"sia","t":"...Em uma reviravolta dramática, tentaram tirar a vida do rei Reinhold."},{"a":"sia","t":"Azuma parece estar por trás disso. Agente Swan vai dirigir as investigações."},{"a":"king","t":"Sia! O que está fazendo?"},{"a":"sia","t":"Ah, só escrevendo uma carta, não se preocupe."},{"a":"sia","t":"(Meu relatório para o imperador Kern...)"},{"a":"king","t":"Muito bem! Dignitários estrangeiros aguardam a minha presença."},{"a":"king","t":"Eles podem estar um tanto... ofendidos pelo último passeio de compras."},{"a":"king","t":"Eu apreciaria a sua ajuda em resolver a situação!"},{"a":"sia","t":"É claro. Já vou, meu rei."},{"a":"sia","t":"Se o imperador Kern ficar sabendo dessa tentativa de assassinato, poderemos sofrer consequências terríveis..."},{"a":"sia","t":"Eu... preciso pensar. Este reino... não está pronto para enfrentar Kern."},{"a":"sia","t":"Em nome da segurança de todos... Talvez seja melhor omitir esse detalhe..."},{"a":"sia","t":"Está tudo indo conforme o planejado. Agente Swan não tem nada a relatar este mês."}]},{"id":"sia_06","i":6,"title":"Pedras e sapatos","req":"sia:6","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"king","t":"Sia! Você tem visita! Um rapaz principesco, eu diria."},{"a":"sia","t":"...Principesco, meu rei? Não pode ser..."},{"a":"donovan","t":"Lady Sia."},{"a":"sia","t":"...Donovan."},{"a":"sia","t":"Meu rei, há um problema urgente no seu tesouro. Recomendo verificar imediatamente."},{"a":"king","t":"Ah, o último carregamento de Ouro Puro chegou? Mal posso esperar!"},{"a":"donovan","t":"Este rei é sempre muito bobo, não?"},{"a":"sia","t":"Que ventos nefastos trazem você ao reino de Reinhold, alquimista?"},{"a":"donovan","t":"Direto ao ponto como sempre, Agente Swan."},{"a":"donovan","t":"Estou de licença por motivos pessoais. Com a permissão do imperador de Kern, é claro."},{"a":"donovan","t":"Cheirando as flores, provando as poções... Férias de alquimista, por assim dizer."},{"a":"sia","t":"E você decidiu vir justamente para cá?"},{"a":"donovan","t":"Este reino retrógrado parece ter uma boa quantidade de alquimistas habilidosos."},{"a":"donovan","t":"...Mas se descobrirem que a lealdade de Swan está vacilando..."},{"a":"sia","t":"Você já provou o que queria, Donovan. Pode aproveitar suas... férias."},{"a":"donovan","t":"Como quiser, Lady Sia. Um prazer, como sempre."},{"a":"sia","t":"...Mais uma pedra no meu sapato."}]},{"id":"sia_07","i":7,"title":"Estranho da Cidade de Ouro","req":"sia:7","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"sia","t":"Donovan? Espero não estar interrompendo nenhuma... espionagem."},{"a":"donovan","t":"Ah! Lady Sia!"},{"a":"donovan","t":"Não, não mesmo! Estava só dando uma olhada."},{"a":"sia","t":"Não precisa guardar segredos. Todos são bem-vindos na Cidade Perdida de Ouro."},{"a":"sia","t":"Contudo, lembre-se de que, de acordo com a lei do Reino, todo e qualquer <c1>Ouro Puro</c1> encontrado pertence ao Rei Reinhold."},{"a":"sia","t":"Em troca, bravos aventureiros são recompensados por suas contribuições."},{"a":"donovan","t":"Entendi. Um rei bem... generoso."},{"a":"donovan","t":"O <c1>Ouro Puro</c1> é usado em moedas, o que resulta em uma inflação acentuada..."},{"a":"sia","t":"Isso mesmo. Estou vendo que você está interceptando minhas correspondências com o Imperador."},{"a":"donovan","t":"Eu gosto de saber de tudo."},{"a":"sia","t":"Já que você está aqui, seja útil e leve um pouco de <c1>Ouro Puro</c1> para o castelo."},{"a":"donovan","t":"Claro. Tudo por minha senhora."},{"a":"sia","t":"Tente não quebrar uma unha na volta, caro Donovan."}]},{"id":"sia_08","i":8,"title":"Na Encruzilhada do Destino","req":"sia:8","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"tavern","t":"Meu lindo Cisne voltou! Tão pontual, como esperado do nosso grande administrador."},{"a":"sia","t":"Eu atendi ao seu chamado, Naya intrometida. Não estou de bom humor, então fale logo."},{"a":"tavern","t":"Então, ele vai ficar ainda pior! Interceptei as correspondências de um certo alquimista..."},{"a":"tavern","t":"E magicartas expressas também! Vou te contar, pegar elas não foi nada fácil!"},{"a":"sia","t":"Não diga que..."},{"a":"tavern","t":"Parece que esse Donovan acabou descobrindo o nosso joguinho."},{"a":"sia","t":"Mas se você interceptou as cartas..."},{"a":"tavern","t":"Isso mesmo, elas não vão a lugar nenhum! Se você pagar, claro."},{"a":"sia","t":"Eu... Certo. Diga quanto quer, Naya. Eu pago."},{"a":"tavern","t":"Eu aumentei os meus preços. Quero uma recompensa especial por elas."},{"a":"sia","t":"Muito bem. Nesse caso, eu..."},{"a":"tavern","t":"Escolha um lado, Sia. Esse é o meu preço."},{"a":"sia","t":"..."},{"a":"tavern","t":"Se ficar em cima do muro, vai acabar caindo... e parece que você já perdeu o equilíbrio."},{"a":"tavern","t":"Mas dependendo da sua resposta, eu posso aliviar sua queda, claro..."}]},{"id":"sia_09","i":9,"title":"Cadeia de Traição","req":"sia:9","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"sia","t":"Caro Donovan. Tenho um pedido a fazer."},{"a":"donovan","t":"É? Vamos ouvir, então."},{"a":"sia","t":"Vá ao Imperador. Diga que Agente Swan morreu. Uma morte honrosa e trágica enquanto servia fielmente ao Império."},{"a":"donovan","t":"P-Perdão?"},{"a":"sia","t":"Pra mim já chega, Donovan. Vou trocar de lado, por assim dizer."},{"a":"sia","t":"E é você que vai dar a notícia. E sustentar minha história, é claro."},{"a":"donovan","t":"Q-Que ultraje! Isso é traição! Eu jamais..."},{"a":"sia","t":"Acredito que vai me ajudar, Donovan. A não ser, é claro, que queira que todos descubram a receita do seu elixir de imortalidade."},{"a":"donovan","t":"Ah, vai blefar assim, agora, Sia? Nunca falei da receita a ninguém. Não tem como..."},{"a":"sia","t":"O que era mesmo? Asas de efemérida de cem anos... água do Estige...?"},{"a":"donovan","t":"I-Isso..."},{"a":"sia","t":"Eram tantos ingredientes! Também tinha uma pitada de vinho, para dar gosto?"},{"a":"donovan","t":"B-Basta. BASTA! Não sei por que meios nefastos você descobriu..."},{"a":"sia","t":"Parece que você subestimou minha rede de espionagem."},{"a":"donovan","t":"Mas eu vou ceder ao seu joguinho. Por ora."},{"a":"sia","t":"Você não sabe perder, não é? Acho que a minha oferta é mais que generosa."},{"a":"sia","t":"O que é uma traiçãozinha em troca do trabalho da sua vida?"}]},{"id":"sia_10","i":10,"title":"Auxílio póstumo","req":"sia:10","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"sia","t":"Agente Sussurro. Sou eu."},{"a":"essence","t":"*Bocejo*... assim cedo?"},{"a":"sia","t":"Suas informações estavam corretas. Vou elogiar seu trabalho estelar."},{"a":"essence","t":"Não é... nada..."},{"a":"sia","t":"Donovan sempre foi um homem cauteloso, mas acho que nada pode impedir um fantasma de espiar!"},{"a":"essence","t":"Total..."},{"a":"essence","t":"Ele parecia... bem irritado..."},{"a":"sia","t":"Como combinamos, vou levar o seu pagamento até o seu túmulo como uma oferenda."},{"a":"sia","t":"E também vou deixar um adicional. Agora vá perturbar o Donovan mais um pouquinho."},{"a":"essence","t":"Me pagam... pra fazer coisas de fantasma. Que maravilha."}]},{"id":"sia_11","i":11,"title":"O Voo do Cisne","req":"sia:11","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"king","t":"Sia! Não aguento mais! Quanto tempo preciso esperar até lançar meus caprichos no mundo?!"},{"a":"sia","t":"Faltam só alguns dias, Majestade. Por favor, tenha só um pouco mais de paciência."},{"a":"king","t":"Ah! E qual é o motivo de tanta papelada?"},{"a":"sia","t":"Certidões de nascimento e outros documentos administrativos importantes do meu interesse."},{"a":"sia","t":"Parece que, por mera coincidência, vários documentos da minha vida neste reino desapareceram."},{"a":"sia","t":"Desde então estou preenchendo esses formulários com o que lembro."},{"a":"king","t":"Claro! A minha maior conselheira precisa ser uma moradora oficial do meu reino!"},{"a":"king","t":"Aqui! Eu darei a chancela real a todos eles imediatamente!"},{"a":"king","t":"Prontinho! Você não deixa escapar nada, como sempre!"},{"a":"sia","t":"Obrigada, Alteza. Espero servir por muitas décadas."},{"a":"king","t":"Eu torço para que sim!"},{"a":"king","t":"Sia, por acaso estou vendo uma lágrima? Preencher esses papeis deixa você tão alegre assim?"},{"a":"sia","t":"Ah... não. Na verdade, eu diria que essa papelada me faz chorar de tédio."},{"a":"sia","t":"Mas agora... Vamos discutir os seus caprichos?"},{"a":"king","t":"Vamos! Se quer saber, a situação atual dos Escudos..."}]}]},{"id":"atlab_sokka","name":"Sokka","chapters":[{"id":"atlab_sokka_01","i":1,"title":"O Grande Guerreiro Sokka","req":"atlab_sokka:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fichas da fortuna"},"side":false,"lines":[{"a":"atlab_aang","t":"E que tal... isso?"},{"a":"tavern","t":"Ah, que truque legal!"},{"a":"atlab_sokka","t":"Ugh. Ele faz isso o tempo todo!"},{"a":"argon","t":"Oi, Sokka, né? Eu sou Argon!"},{"a":"atlab_sokka","t":"Ah, e aí. Se você quer ver truques de dobras, é com o Aang que precisa falar."},{"a":"argon","t":"Ah, não. Eu não entendo muito de magia, nem de dobras."},{"a":"argon","t":"Mas, a julgar pelo seu equipamento, você deve ser um bravo guerreiro."},{"a":"atlab_sokka","t":"Um bravo guerreiro?"},{"a":"atlab_sokka","t":"É-É sou mesmo! Eu sou Sokka, o Grande Guerreiro da Equipe Avatar!"},{"a":"argon","t":"Eu sabia! Você deve ter histórias incríveis para contar!"},{"a":"atlab_sokka","t":"E tenho mesmo! Teve uma vez, no cerco de Agna Qel'a..."},{"a":"atlab_sokka","t":"E foi assim que a minha namorada na época acabou virando a lua."},{"a":"argon","t":"A... a lua!?"},{"a":"atlab_sokka","t":"É. Mas aí, a frota da Nação do Fogo..."},{"a":"atlab_sokka","t":"... e aí pei! Eu derrubei o homem corujão na biblioteca."},{"a":"argon","t":"Uau! Mas essa coruja não era um espírito poderoso?"},{"a":"atlab_sokka","t":"Era sim! Mas a Equipe Avatar sempre vence quando o Sokka está por perto!"},{"a":"atlab_sokka","t":"...Falando nisso, cadê o Aang?"},{"a":"argon","t":"Ah, ele saiu faz uma hora."},{"a":"atlab_sokka","t":"Droga! Eu perdi a noção do tempo. Foi mal, Argon, tenho que correr!"}]},{"id":"atlab_sokka_02","i":2,"title":"O Grande Ferreiro Sokka","req":"atlab_sokka:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fichas da fortuna"},"side":false,"lines":[{"a":"blacksmith","t":"Trabalhando duro, Sokka?"},{"a":"atlab_sokka","t":"E aí, Wallace. Obrigado por deixar eu usar suas ferramentas!"},{"a":"blacksmith","t":"Relaxa! Não esperava que você fosse um artesão tão bom nessa idade!"},{"a":"atlab_sokka","t":"Quando você o único no grupo que não pode dobrar, tem que aprender todo tipo de coisa."},{"a":"atlab_sokka","t":"Não é todo dia que eu posso usar ferramentas boas como essas..."},{"a":"atlab_sokka","t":"A manutenção vai acabar rapidinho!"},{"a":"blacksmith","t":"Essa espada que está afiando... onde você conseguiu?"},{"a":"atlab_sokka","t":"Essa é minha Espada Espacial! Eu mesmo que forjei!"},{"a":"blacksmith","t":"Metal estelar? Nada mal, garoto!"},{"a":"blacksmith","t":"Deve ser... de outro mundo!"},{"a":"atlab_sokka","t":"Pode apostar! Não existe espada melhor!"},{"a":"polonia","t":"Ahoy! Desculpa interromper, mas algum de vocês rapazotes pode me ajudar a consertar meu navio?"},{"a":"polonia","t":"Ele tá meio ranzinza hoje. Bateu numas bolas de ferro e acabou encalhando..."},{"a":"blacksmith","t":"Parece uma embarcação de problemas!"},{"a":"atlab_sokka","t":"Ei, sem problemas, eu sou da Tribo da Água! Vou ver o que posso fazer. Foi mal, Wallace, tenho que ir!"},{"a":"blacksmith","t":"Vou consertar o resto dos seus equipamentos enquanto isso. Boa sorte!"}]},{"id":"atlab_sokka_03","i":3,"title":"O Grande Navegador Sokka","req":"atlab_sokka:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fichas da fortuna"},"side":false,"lines":[{"a":"atlab_sokka","t":"Pronto, isso deve pelo menos te levar até o porto."},{"a":"polonia","t":"Isso que é conserto. Está tudo perfeito!"},{"a":"atlab_sokka","t":"... Seu leme está preso com madeira de naufrágio e pedaços da minha camisa."},{"a":"atlab_sokka","t":"Eu não diria \"perfeito\". Está mais para estilo Sokka."},{"a":"polonia","t":"Yo ho ho! Mas como um marinheiro de água doce como você aprendeu a consertar navios?"},{"a":"atlab_sokka","t":"A vida na Tribo da Água é cheia de navios e pesca. Eu aprendi a navegar antes de andar."},{"a":"atlab_sokka","t":"Não faz muito tempo, pensei num submarino que usa a dobra de água para se mover!"},{"a":"polonia","t":"Você está falando em marinheiro-de-água-docês. O que é isso aí?"},{"a":"atlab_sokka","t":"É... é como um navio de metal que anda embaixo d'água."},{"a":"polonia","t":"Para mim você tá é mandando marinheiros pro Baú do Davy Jones numa caixinha chique."},{"a":"engineer","t":"Eu ouvi \"protótipo extremamente perigoso e não testado\"?"},{"a":"atlab_sokka","t":"Ah... não exata..."},{"a":"engineer","t":"Eu gostei do seu estilo. Vem comigo, novato."},{"a":"polonia","t":"Yo ho ho, de volta ao mar! Levantar âncoras antes que os caçadores de recompensa cheguem aqui!"},{"a":"polonia","t":"Arr, melhor fugir das bolas de ferro flutuantes dessa vez."}]},{"id":"atlab_sokka_04","i":4,"title":"O Grande Inventor Sokka","req":"atlab_sokka:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fichas da fortuna"},"side":false,"lines":[{"a":"engineer","t":"Fascinante! Vou ser sincero, seu projeto é meio fajuto..."},{"a":"engineer","t":"... Mas, com um pouquinho de trabalho, acho que esse submarino pode funcionar!"},{"a":"atlab_sokka","t":"Genial, né? Eu sabia!"},{"a":"atlab_sokka","t":"Mas lembre que ele foi feito para ser operado por dobradores de água."},{"a":"engineer","t":"Mero detalhe. Vamos dar um jeito."},{"a":"engineer","t":"Só pense! Com isso, podemos explorar o Templo Afundado!"},{"a":"atlab_sokka","t":"Ah, e ele não guarda muito ar, então as viagens precisam ser curtas."},{"a":"atlab_sokka","t":"...Você está ouvindo?"},{"a":"engineer","t":"Não se apoie nessa bolona de ferro."},{"a":"atlab_sokka","t":"...Quê? Ah! Por que não?"},{"a":"engineer","t":"É meu protótipo de bomba marinha. Não encoste. É muito explosivo."},{"a":"atlab_sokka","t":"...Ah."},{"a":"atlab_sokka","t":"Enfim, me avise do progresso desse protótipo."},{"a":"atlab_sokka","t":"Se funcionar... poderemos usá-lo no futuro."}]}]},{"id":"leather","name":"Tamas","chapters":[{"id":"leather_farewell","i":0,"title":null,"req":null,"reward":null,"side":false,"lines":[{"a":"leather","t":"Sabe, cara, acho que cansei de ser Campeão."},{"a":"leather","t":"Tem bem mais responsabilidades do que eu pensava, cara. Mal tive tempo pro meu couro!"},{"a":"leather","t":"Talvez eu tente de novo no ano que vem, cara. Te vejo na cidade!"}]},{"id":"leather_01","i":1,"title":"Couro e a Árvore","req":"leather:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fichas da fortuna"},"side":false,"lines":[{"a":"leather","t":"Valeu pela ajuda, cara."},{"a":"argon","t":"Sem problemas, Tamas! Quanto couro!"},{"a":"leather","t":"Hoje o lote foi enorme. Mas olha onde pisa."},{"a":"argon","t":"Pois é... não é fácil andar por aqui... Opa!"},{"a":"leather","t":"Ai! Puxa!"},{"a":"argon","t":"Desculpe, Tamas! Você se machucou?"},{"a":"leather","t":"Foi só uma batida na cabeça, cara. Acho que tô bem."},{"a":"leather","t":"... Acabo de ter uma ideia de gênio, cara."},{"a":"leather","t":"É sério mesmo, cara. Tenho que ir."},{"a":"argon","t":"Hum, beleza! Que bom que pude ajudar!"},{"a":"argon","t":"... Mas o que eu faço agora com todo esse couro espalhado?..."}]},{"id":"leather_02","i":2,"title":"Profetizado pela Profecia","req":"leather:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fichas da fortuna"},"side":false,"lines":[{"a":"leather","t":"... e foi assim que bati a cabeça, cara. Fiquei até com um galo."},{"a":"mana","t":"Tudo o que posso fazer é ouvir, mas não ajudar."},{"a":"mana","t":"Os fluxos do éter adivinham e revelam, mas não curam."},{"a":"leather","t":"Mas é magia, não é? Ah, cara, é só usar suas mãos mágicas."},{"a":"mana","t":"Não há nada..."},{"a":"mana","t":"!!!..."},{"a":"mana","t":"Esse... destino!... Devastador!..."},{"a":"leather","t":"Será que funcionou mesmo, cara? Ainda me sinto meio tonto."},{"a":"mana","t":"Perdão... Uma nova visão veio a mim, e ela exigirá meditação."},{"a":"mana","t":"Peça o auxílio da Escolhida da Deusa para curar seus... ferimentos. Devo partir imediatamente."},{"a":"leather","t":"Beleza, cara. Vou só andar e ver se passa, tô bem de saúde esses tempos."}]},{"id":"leather_03","i":3,"title":"A União dos Campeões","req":"leather:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fichas da fortuna"},"side":false,"lines":[{"a":"argon","t":"Temos um novo, er... Campeão na área."},{"a":"polonia","t":"Ora, ora! Tomara que seja bonitão!"},{"a":"leather","t":"E aí, caras."},{"a":"polonia","t":"Pelo dente da serpente! Isso é sério?"},{"a":"lilu","t":"Tamas! Quando você..."},{"a":"leather","t":"Decidi dar uma chance a esse lance de Campeão, cara. Não parece tão difícil."},{"a":"argon","t":"Hum... Tamas, que tal nos contar o que você faz?"},{"a":"leather","t":"Dou porrada nos monstros, cara. E também farejo itens de couro a milhas de distância."},{"a":"polonia","t":"Ei! Roubar coisas é só comigo! Procure outra coisa pra fazer!"},{"a":"leather","t":"Não é roubo, cara. O povo é que vive largando tudo isso por aí."},{"a":"lilu","t":"Parece que as coisas ficarão interessantes por aqui!"},{"a":"polonia","t":"Imagino que sim..."}]},{"id":"leather_04","i":4,"title":"Herói Desconhecido","req":"leather:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Fichas da fortuna"},"side":false,"lines":[{"a":"sia","t":"Meu Rei, trago novidades um tanto quanto inusitadas."},{"a":"king","t":"Sou todo ouvidos, como sempre! Vá em frente!"},{"a":"sia","t":"Dizem os heróis e as caravanas que as estradas estão mais seguras do que nunca."},{"a":"sia","t":"Há poucos relatos de monstros; parecem até estar com medo de atacar alguém."},{"a":"king","t":"Esplêndido!"},{"a":"sia","t":"Contudo, não conseguimos identificar o motivo desse comportamento estranho."},{"a":"sia","t":"Igualmente estranha é uma queda abrupta e repentina no mercado de artigos de Couro..."},{"a":"king","t":"Uma coincidência e nada mais! Vamos fazer um banquete para celebrar as boas notícias!"},{"a":"sia","t":"Talvez, meu Rei... talvez."}]}]},{"id":"yami","name":"Yami","chapters":[{"id":"yami_01","i":1,"title":"A andarilha azuman","req":"yami:1","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"monster_forest_Boss","t":"Hehehe! O que temos aqui?"},{"a":"yami","t":"Hunf. Suma daqui, peste."},{"a":"monster_forest_Boss","t":"Você não tem boas maneiras, senhorita! E usa roupas estranhas!"},{"a":"yami","t":"..."},{"a":"monster_forest_Boss","t":"Ah hah! Você tem o cheiro de Azuma, o reino humano oriental!"},{"a":"monster_forest_Boss","t":"O que traz você até aqui, senhorita?"},{"a":"monster_forest_Boss","t":"Armada até os dentes e com os lábios cerrados... Você é uma assassina, certo?"},{"a":"yami","t":"..."},{"a":"monster_forest_Boss","t":"Hehe! Eu sabia! Humanos estúpidos, sempre matando uns aos outros!"},{"a":"yami","t":"...Você está certo. Eu viajei até aqui para matar um rei tirânico."},{"a":"monster_forest_Boss","t":"Bem! Você não pode ser uma boa assassina se contar isso para todo mundo! Por que contou para mim?"},{"a":"yami","t":"Porque você não viverá para contar a ninguém. Adeus."},{"a":"monster_forest_Boss","t":"Eita!"},{"a":"yami","t":"...Rei Reinhold, você é o próximo."}]},{"id":"yami_02","i":2,"title":"Cace ou seja caçado","req":"yami:2","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"yami","t":"...A segurança do castelo é rigorosa."},{"a":"yami","t":"Um sistema de senha que muda diariamente..."},{"a":"yami","t":"Patrulhas não programadas..."},{"a":"yami","t":"Preciso ter..."},{"a":"argon","t":"Olá! Você aí, nos arbustos!"},{"a":"yami","t":"...!"},{"a":"argon","t":"Você está aqui para se tornar uma cavaleira também?"},{"a":"argon","t":"Sia estará aqui em breve! Não precisa se esconder, ela é bem legal!"},{"a":"yami","t":"Sia...!"},{"a":"yami","t":"Eu preciso ir. Adeus."},{"a":"argon","t":"E-espere!"},{"a":"argon","t":"Uau! Bomba de fumaça!?"},{"a":"yami","t":"...Aquele tolo escapou."},{"a":"yami","t":"Com Sia aqui... minha tarefa será difícil."},{"a":"yami","t":"Mas preciso fazer isso. Eu não posso falhar."},{"a":"yami","t":"Pela Ordem... e pelo bem da minha irmã."}]},{"id":"yami_03","i":3,"title":"Momento decisivo","req":"yami:3","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"king","t":"Estimado povo do meu reino! Obrigado por comparecerem ao meu suntuoso banquete!"},{"a":"king","t":"É também uma oportunidade perfeita para todos me admirarem! Não percam essa chance!"},{"a":"yami","t":"(Tirano pomposo. Típico.)"},{"a":"sia","t":"Hm, sim. Obrigado por este discurso edificante, sua majestade."},{"a":"sia","t":"Nós reunimos vocês aqui hoje para celebrar a incrível generosidade do Rei."},{"a":"sia","t":"Nos últimos meses, ele doou vários milhões de ouro de seus próprios cofres..."},{"a":"sia","t":"...Para vários templos, escolas e orfanatos locais."},{"a":"sia","t":"Todos são bem-vindos a participar, então contem para seus amigos e familiares."},{"a":"sia","t":"Vida longa ao Rei Reinhold!"},{"a":"yami","t":"(...Estas não são ações de um tirano.)"},{"a":"yami","t":"(...Não, a Ordem não mentiria. Isso deve ser um truque.)"},{"a":"yami","t":"Tirano Reinhold, seu reinado termina agora!"},{"a":"sia","t":"Uma shuriken...! A assassina azuman!"},{"a":"yami","t":"Eu errei...!? Impossível!"},{"a":"sia","t":"Guardas! Bloqueiem todas as saídas! Capturem esta mulher imediatamente!"}]},{"id":"yami_04","i":4,"title":"Reflexão","req":"yami:4","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"yami","t":"(Eu hesitei... e fracassei.)"},{"a":"yami","t":"(Será que a Ordem mentiu...?)"},{"a":"yami","t":"(Não importa. Estou sozinha agora.)"},{"a":"argon","t":"Finalmente encontrei você!"},{"a":"yami","t":"O tolo cavaleiro!"},{"a":"argon","t":"Ei! Eu não estou aqui para lutar!"},{"a":"yami","t":"Eu não vou cair nos seus truques, cão do Reinhold!"},{"a":"argon","t":"...Você errou de propósito, não é?"},{"a":"yami","t":"...!"},{"a":"argon","t":"Eu vi você no banquete. Parecia que você tinha se arrependido de ter lançado aquela shuriken."},{"a":"argon","t":"O Rei não é uma má pessoa, sabia? Ele é um pouco estranho às vezes, mas ele faz o seu melhor!"},{"a":"argon","t":"Eu não sei quem te pagou para fazer isso, mas não devem ser pessoas boas..."},{"a":"argon","t":"Que tal voltar ao castelo e pedir desculpas? Tenho certeza de que Reinhold..."},{"a":"yami","t":"...Pedir desculpas? Que idiotice."},{"a":"yami","t":"Tenho muito em que pensar. Não me siga, se você dá valor à sua vida."},{"a":"argon","t":"...Ela não é uma pessoa ruim, tenho certeza disso."},{"a":"argon","t":"Agora preciso falar com a Sia..."},{"a":"argon","t":"Caramba, vou levar a maior bronca..."}]},{"id":"yami_05","i":5,"title":"À luz do luar","req":"yami:5","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"fabric","t":"<sprite tint=1 name=Note1>O sol brilha nos salgueiros altos, o resplendor de eras ancestrais<sprite tint=1 name=Note2>..."},{"a":"fabric","t":"<sprite tint=1 name=Note2>Da senda élfica, nós... Aaaaah!"},{"a":"yami","t":"O frio que você está sentindo é a minha lâmina no seu pescoço."},{"a":"yami","t":"Eu tenho perguntas. Responda com sinceridade, e talvez te deixe viver."},{"a":"fabric","t":"Aaah! S-sim! Qualquer c- Ai!"},{"a":"yami","t":"Silêncio."},{"a":"yami","t":"O tolo que você chama de rei... Fale sobre ele."},{"a":"fabric","t":"R-rei Reinhold? Ele governa essas terras..."},{"a":"fabric","t":"Por mais que seja meio excêntrico, não dá pra negar sua virtude e generosidade."},{"a":"fabric","t":"...Ele é meio inexperiente, mas Sia, sua nova conselheira, mais do que compensa!"},{"a":"yami","t":"Impossível...! Suas palavras fedem a covardia, mas soam verdadeiras."},{"a":"yami","t":"Na cidade! Tem um oráculo aqui?"},{"a":"fabric","t":"Ah! Sim! A elfa, Serene, no alto do monte!"},{"a":"fabric","t":"Estranha misteriosa... Posso ter a honra de saber o seu no- Ai!"},{"a":"yami","t":"Alguns dias atrás, eu teria matado você sem pensar duas vezes. Não desperdice a sua sorte."},{"a":"yami","t":"Volte à sua vida vazia e esqueça tudo que aconteceu aqui."},{"a":"fabric","t":"...Ufa! Que encontro estimulante!"},{"a":"fabric","t":"Dama vestida de negro... Será que vamos nos ver de novo?"}]},{"id":"yami_06","i":6,"title":"Peão quebrado","req":"yami:6","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"mana","t":"...Um vento negro trai a presença da Perseguidora."},{"a":"yami","t":"...! Como?"},{"a":"mana","t":"Aquela Que Persegue tem passos leves, mas seu coração pesado é visível ao terceiro olho."},{"a":"yami","t":"...Chega de enigmas, oráculo. Eu preciso de respostas."},{"a":"yami","t":"Sobre a Ordem... A minha família."},{"a":"mana","t":"Uma assassina vem em busca de orientação. O que ela oferece em troca?"},{"a":"yami","t":"Sua vida."},{"a":"mana","t":"...Que seja."},{"a":"mana","t":"<c1>A Ordem de Azuman, antes preocupada em corrigir as injustiças...</c1>"},{"a":"mana","t":"<c1>...Campeões da ordem, agora escravos do dinheiro...</c1>"},{"a":"mana","t":"<c1>...Para uma tarefa insuperável, sacrifica-se um peão...</c1>"},{"a":"mana","t":"<c1>...Tanto no sucesso quanto no fracasso, a Ordem emerge vitoriosa.</c1>"},{"a":"yami","t":"...Impossível."},{"a":"mana","t":"O mensageiro falou."},{"a":"yami","t":"...IMPOSSÍVEL!"},{"a":"mana","t":"..."},{"a":"mana","t":"Aqueles que andam nas sombras também precisam se haver com a luz, em algum momento."}]},{"id":"yami_07","i":7,"title":"Peão quebrado","req":"yami:7","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"yami","t":"... Preciso pegar as minhas coisas e ir embora o mais rápido possível."},{"a":"inn","t":"Olá, estranha misteriosa."},{"a":"yami","t":"Estalajadeiro. Eu paguei a mais pelo seu silêncio."},{"a":"inn","t":"Não precisa se preocupar, não metemos o nariz onde não devemos aqui na Estalagem da Esmeralda!"},{"a":"inn","t":"Mas recebemos alguns visitantes mal-encarados que pareciam estar procurando você."},{"a":"yami","t":"(Agentes da Ordem? Já?)"},{"a":"inn","t":"Eles não disseram os seus nomes. Um povo suspeito. São amigos seus?"},{"a":"yami","t":"Não mais. Diga que eu morri. Talvez eu morra mesmo."},{"a":"inn","t":"Saindo com pressa, né? Eu pensei nisso mesmo. Então preparei algumas coisas para você."},{"a":"yami","t":"... Obrigada, estalajadeiro. Mas, para onde vou, não preciso de nada."}]},{"id":"yami_08","i":8,"title":"Viagem sem volta","req":"yami:8","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"sia","t":"Você disse Pico da Desolação?"},{"a":"wood","t":"É, eu vi uma menina parecida com um ninja que combina com a sua descrição. Ela parecia estar com pressa."},{"a":"sia","t":"Excelente. Finalmente encontramos a nossa assassina."},{"a":"sia","t":"Vou reunir uma patrulha e..."},{"a":"wood","t":"Tem certeza? Acho que não é necessário."},{"a":"sia","t":"... Por que não, Gorza?"},{"a":"wood","t":"Uma expedição solo ao Pico da Desolação é suicídio. E aquela menina não levou mantimentos."},{"a":"wood","t":"E é claro que ela sabe disso. Nem o Rudo é burro de ir lá sozinho."},{"a":"sia","t":"É mesmo? Obrigada, Gorza, vou lembrar disso."},{"a":"sia","t":"Acho que esse problema vai se resolver sozinho, mas..."},{"a":"sia","t":"... parece uma vitória vazia. No que você está pensando, assassina?"}]},{"id":"yami_09","i":9,"title":"Confronto da Desolação (Yami)","req":"yami:9","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"argon","t":"Deve ser o destino. Uma recompensa ainda maior que a Harpia!"},{"a":"yami","t":"... Pode vir. Eu vou matar você aí mesmo."},{"a":"argon","t":"É o que você diz, mas não parece ter muita certeza..."},{"a":"yami","t":"... É verdade. Eu já não me importo com nada."},{"a":"yami","t":"Se você quiser mesmo que eu morra, então me deixe aqui para morrer."},{"a":"argon","t":"Eu nunca deixaria alguém para morrer! Vou te levar de volta para o Rei Reinhold!"},{"a":"argon","t":"Tenho certeza de que ele vai entender! Eu vou te carregar, se precisar!"},{"a":"yami","t":"..."},{"a":"argon","t":"Pode vir, sobe!"},{"a":"argon","t":"Espera aí, você está só carne e osso! Quando você comeu pela última vez?"},{"a":"yami","t":"..."},{"a":"argon","t":"É melhor comer alguma coisa na descida, vai ser uma viagem turbulenta!"}]},{"id":"yami_10","i":10,"title":"Por trás das linhas inimigas","req":"argon:10","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"sia","t":"Guardas! Tragam reforços e observem todos os passos dela!"},{"a":"sia","t":"Argon, espere lá fora enquanto conversamos com esta... intrusa."},{"a":"argon","t":"Já!"},{"a":"sia","t":"Agora. Fale, assassina."},{"a":"yami","t":"Hunf, tudo bem. Eu fui contratada para matar um tirano."},{"a":"yami","t":"Ou assim eu pensei. Parece que ele é apenas um bufão bem-educado."},{"a":"king","t":"Um bufão!?"},{"a":"sia","t":"O que o seu povo tem contra o nosso rei?"},{"a":"yami","t":"Minha ordem ataca apenas em nome da justiça..."},{"a":"yami","t":"Mas parece que isso era mentira. E, com o meu fracasso, eles passaram a me perseguir."},{"a":"yami","t":"Me... perdoem. Eu aceitarei a sua... punição..."},{"a":"yami","t":"...Ugh."},{"a":"king","t":"Ela caiu!"},{"a":"sia","t":"Exausta e com fome..."},{"a":"sia","t":"Guardas! Chamem os nossos melhores médicos para ajudar!"},{"a":"sia","t":"Façam com que ela receba cuidados dignos de um convidado real."}]},{"id":"yami_epilogue","i":11,"title":"Epílogo","req":"yami:10","reward":{"k":"gems","id":"gems","q":10,"n":"Joias"},"side":false,"lines":[{"a":"sia","t":"Uff... Uff... Alcançar você... é uma subida e tanto..."},{"a":"yami","t":"Essa é a minha casa agora."},{"a":"sia","t":"Por que você não aceita morar na cidade? Você foi perdoada."},{"a":"yami","t":"O meu clã provavelmente acredita que estou morta. E quero que continue assim."},{"a":"sia","t":"Eu compreendo. Vou providenciar para que receba alimentos."},{"a":"sia","t":"Agora, para a sua próxima tarefa..."},{"a":"yami","t":"Mais capangas do Império?"},{"a":"sia","t":"Isso mesmo. Como você sabe, sua Majestade é invejada por muitos."},{"a":"sia","t":"Veja este documento com mais informações sobre os seus alvos."},{"a":"yami","t":"Considere feito."},{"a":"sia","t":"É difícil dizer isso, mas acredito em você."},{"a":"sia","t":"É melhor eu voltar. Mas não quero nem pensar no caminho..."},{"a":"yami","t":"Sia... Reinhold..."},{"a":"yami","t":"... Obrigada. De verdade."}]}]}];
